func.func @main(%idx: tensor<5xi32>) -> tensor<5x8xf32> {
  %c8 = stablehlo.constant dense<8> : tensor<i32>
  %c0f = stablehlo.constant dense<0.0> : tensor<f32>
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>

  // Create a 1D tensor [0,1,2,3,4,5,6,7]
  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx from [5] to [5x8]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast iota from [8] to [5x8]
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_bcast == iota_bcast
  %eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Check idx in [0,7]: idx >= 0 and idx < 8
  %zero = stablehlo.constant dense<0> : tensor<i32>
  %ge0 = "stablehlo.compare"(%idx, %zero) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>
  %lt8 = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>
  %in_range = "stablehlo.and"(%ge0, %lt8) : (tensor<5xi1>, tensor<5xi1>) -> tensor<5xi1>

  // Broadcast in_range from [5] to [5x8]
  %in_range_bcast = "stablehlo.broadcast_in_dim"(%in_range) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Select: if in_range then eq else false (all zeros)
  %out_pred = "stablehlo.and"(%eq, %in_range_bcast) : (tensor<5x8xi1>, tensor<5x8xi1>) -> tensor<5x8xi1>

  // Convert bool tensor to float: select out_pred ? 1.0 : 0.0
  %out = "stablehlo.select"(%out_pred, %c1f, %c0f) : (tensor<5x8xi1>, tensor<f32>, tensor<f32>) -> tensor<5x8xf32>

  return %out : tensor<5x8xf32>
}
