  %eq = stablehlo.compare %bidx, %biota 
    {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>
  // Create constant 1.0f tensor of shape [5x8]
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one5x8 = stablehlo.broadcast_in_dim %one 
    {broadcast_dimensions = dense<array<i64: 0, 1>> : tensor<2xi64>} : (tensor<f32>) -> tensor<5x8xf32>
  // Create constant 0.0f tensor of shape [5x8]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero5x8 = stablehlo.broadcast_in_dim %zero 
    {broadcast_dimensions = dense<array<i64: 0, 1>> : tensor<2xi64>} : (tensor<f32>) -> tensor<5x8xf32>
