  %sel = stablehlo.select %eq, %one5x8, %zero5x8 : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>
  // Now mask out rows where idx[n] is outside [0..7]
  // Create constants for bounds
  %zero_i32 = stablehlo.constant dense<0> : tensor<i32>
  %seven_i32 = stablehlo.constant dense<7> : tensor<i32>
  // Broadcast idx to [5x8] again for bounds check (reuse %bidx)
  // Check idx >= 0
  %ge0 = stablehlo.compare %bidx, 
    stablehlo.broadcast_in_dim %zero_i32 {broadcast_dimensions = dense<array<i64: 0>>} : (tensor<5x8xi32>, tensor<1xi32>) -> tensor<5x8xi1>
  // Check idx <= 7
  %le7 = stablehlo.compare %bidx, 
    stablehlo.broadcast_in_dim %seven_i32 {broadcast_dimensions = dense<array<i64: 0>>} : (tensor<5x8xi32>, tensor<1xi32>) -> tensor<5x8xi1>
  // Combine bounds: ge0 AND le7
  %valid = stablehlo.compare %ge0, %le7 
    {comparison_direction = #stablehlo<comparison_direction AND>, compare_type = #stablehlo<comparison_type NOTYPE>} : (tensor<5x8xi1>, tensor<5x8xi1>) -> tensor<5x8xi1>
