  %ge0_1d = stablehlo.compare %idx, %zero_i32 : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
  %le7_1d = stablehlo.compare %idx, %seven_i32 : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
