  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast range from [8] to [5x8] with broadcast_dimensions = [1]
  %range_bcast = "stablehlo.broadcast_in_dim"(%range) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_bcast == range_bcast -> [5x8] tensor<i1>
  %eq = "stablehlo.compare"(%idx_bcast, %range_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Check idx in range 0..7: idx >= 0 and idx < 8
  %zero_scalar = "stablehlo.constant"() {value = dense<0> : tensor<i32>} : () -> tensor<i32>
  %zero = "stablehlo.broadcast_in_dim"(%zero_scalar) {broadcast_dimensions = array<i64: 0>} : (tensor<i32>) -> tensor<5xi32>
  %ge0 = "stablehlo.compare"(%idx, %zero) {comparison_direction = #stablehlo<comparison_direction GE>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>
  %lt8 = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>

  // idx_in_range = ge0 AND lt8
  %idx_in_range = "stablehlo.and"(%ge0, %lt8) : (tensor<5xi1>, tensor<5xi1>) -> tensor<5xi1>

  // Broadcast idx_in_range from [5] to [5x8] with broadcast_dimensions = [0]
  %idx_in_range_bcast = "stablehlo.broadcast_in_dim"(%idx_in_range) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Constants 1.0 and 0.0 of shape [5x8]
