  %zero_5x8 = "stablehlo.broadcast_in_dim"(%zero_scalar_f) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<5x8xf32>

  // Select 1.0 where eq and idx_in_range, else 0.0
  %mask = "stablehlo.and"(%eq, %idx_in_range_bcast) : (tensor<5x8xi1>, tensor<5x8xi1>) -> tensor<5x8xi1>
