  // %arg1: linear.weight tensor<7x7xf32>
  // %arg2: linear.bias tensor<7xf32>
  // %arg3: input tensor<6x7xf32>

  // Perform linear: x @ weight^T + bias
  // weight shape: [7,7], input shape: [6,7]
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight needs to be transposed to [7,7] -> [7,7], actually weight is square, but we must transpose to match PyTorch linear:
  // PyTorch linear: output = input @ weight^T + bias
  // So transpose weight: [7,7] -> [7,7] with permutation [1,0]
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot general: batch dims empty, contracting dims input dim 1 and weight dim 0
  %dot = "stablehlo.dot_general"(%arg3, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: bias shape [7], broadcast to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Broadcast constant scalar to [6x7]
  %const_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7xf32>

  // Apply minimum with constant
  %min_out = stablehlo.minimum %linear_out, %const_broadcast : tensor<6x7xf32>

  // Subtract constant
  %result = stablehlo.subtract %min_out, %const_broadcast : tensor<6x7xf32>

  return %result : tensor<6x7xf32>
}
