  %init = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8xf32>
  %init_4x8 = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<4x8xf32>

  // Actually, we need a scalar zero for reduction init
  %zero_scalar = stablehlo.constant dense<0.0> : tensor<f32>

  // Sum over dimension 1 (the 8 elements)
  %sum_exp = "stablehlo.reduce"(%exp_x, %zero_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
