  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0} : (tensor<4xf32>) -> tensor<4x8xf32>

  // Divide exp_x by sum_exp_broadcast to get softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_broadcast : tensor<4x8xf32>

