func.func @main(%arg0: tensor<f32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: constant scalar tensor<f32>
  // %arg1: linear.weight tensor<7x7xf32>
  // %arg2: linear.bias tensor<7xf32>
  // %arg3: input tensor<6x7xf32>

  // Perform linear: x @ weight^T + bias
  // Note: PyTorch Linear weight shape is (out_features, in_features) = (7,7)
  // Input shape: (6,7)
  // So output = input (6x7) dot weight^T (7x7) = (6x7)
  // We need to transpose weight to get (7x7) -> (7x7) but since weight is square,
  // transpose is the same shape, but we must transpose to match dot_general semantics.

  // Transpose weight from (7,7) to (7,7) (swap dims 0 and 1)
  %weight_t = stablehlo.transpose %arg1 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}

  // Dot general: batch dims none, contracting dims: input dim 1 and weight_t dim 0
  %linear_out = stablehlo.dot_general %arg3, %weight_t
    : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>
    {lhs_batching_dimensions = [], rhs_batching_dimensions = [],
     lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]}

  // Add bias: bias shape (7), broadcast to (6,7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %linear_out_bias = stablehlo.add %linear_out, %bias_broadcast : tensor<6x7xf32>

  // Compute minimum with constant scalar
  // Broadcast constant scalar to (6,7)
  %const_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []

  %min_out = stablehlo.minimum %linear_out_bias, %const_broadcast : tensor<6x7xf32>

  // Subtract constant scalar (broadcasted)
  %result = stablehlo.subtract %min_out, %const_broadcast : tensor<6x7xf32>

  func.return %result : tensor<6x7xf32>
}
