func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x7xf32>) -> tensor<8x6x9x9xf32> {
  // %arg0: conv_transpose2d.weight, shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor, shape [batch=8, in_channels=6, height=7, width=7]

  // Step 1: Reverse the kernel spatially (height and width dims)
  // Kernel dims: [in_channels=6, out_channels=6, kernel_h=3, kernel_w=3]
  // Reverse dims 2 and 3 (kernel_h and kernel_w)
  %rev = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Perform convolution with lhs_dilation = stride = 2 (to implement transposed conv with stride=2)
  // The conv_transpose2d in PyTorch with stride=2 means lhs_dilation=2 in stablehlo convolution
  // dimension_numbers: input [b, f, 0, 1] = [batch, in_channels, height, width]
  // kernel [o, i, 0, 1] = [out_channels, in_channels, kernel_h, kernel_w]
  // output [b, f, 0, 1] = [batch, out_channels, height_out, width_out]
  //
  // Note: PyTorch conv_transpose2d weight shape is (in_channels, out_channels/groups, kH, kW)
  // StableHLO convolution expects kernel shape [out_channels, in_channels/groups, kH, kW]
  // So we must swap the first two dims of %rev to get kernel in [o, i, h, w] order.

  // Step 2a: Transpose kernel from [in_channels, out_channels, kH, kW] to [out_channels, in_channels, kH, kW]
  %kernel = "stablehlo.transpose"(%rev) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 3: Convolution parameters
  // stride=1 for convolution (window_strides)
  // lhs_dilation = stride = 2 (to upsample input)
  // rhs_dilation = 1 (no dilation on kernel)
  // padding = 1 (padding=1 in conv_transpose2d)
  // feature_group_count = 1 (groups=1)
  // batch_group_count = 1
  // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]

  %conv = "stablehlo.convolution"(%arg1, %kernel) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x9xf32>

  return %conv : tensor<8x6x9x9xf32>
}

