  // This is not standard, but let's try:
  //
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[i, o, 0, 1, 2]->[b, f, 0, 1, 2]>
  //
  // This will produce output with feature dim = kernel dim 1 = out_channels = 7
  //
