  // rhs_dilation = dilation = 1
  // window_strides = 1
  // padding = 0
  //
  // So we can do:
  // %result = stablehlo.convolution(%arg1, %arg0) {
  //   window_strides = [1,1,1],
  //   padding = [[0,0],[0,0],[0,0]],
  //   lhs_dilation = [1,1,1],
  //   rhs_dilation = [1,1,1],
  //   dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[i, o, 0, 1, 2]->[b, f, 0, 1, 2]>,
  //   feature_group_count = 1,
  //   batch_group_count = 1
