func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x8x8xf32>) -> tensor<6x7x1x1xf32> {
  // Transpose conv: input %arg2 (N=6, C=7, H=8, W=8)
  // weight %arg0 (in_channels=7, out_channels=7, kernel=3x3)
  // PyTorch ConvTranspose2d uses output channels first in weight: (in_channels, out_channels, kH, kW)
  // StableHLO convolution expects kernel dims: [o, i, ...], so we must transpose weight to [o, i, kH, kW]
  // %arg0 shape: 7x7x3x3 (in_channels=7, out_channels=7, kH=3, kW=3)
  // So transpose %arg0 from [in, out, kH, kW] to [out, in, kH, kW]
  %weight_transposed = stablehlo.reshape %arg0 : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>
  %weight_perm = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>

  // ConvTranspose2d with stride=1, padding=1, output_padding=0, dilation=1
  // ConvTranspose2d is a transposed convolution, which can be implemented as a convolution with lhs_dilation
  // lhs_dilation = stride = 1 (no dilation)
  // padding in conv_transpose is padding=1, so padding for convolution is padding=1
  // window_strides = 1
  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw] -> output [b, f, h, w]
  // feature_group_count=1, batch_group_count=1
  %conv = "stablehlo.convolution"(%arg2, %weight_perm) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x8x8xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x8x8xf32>

  // Add bias %arg1 (shape 7) to conv output (6x7x8x8)
  // Broadcast bias to shape 6x7x8x8
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x8x8xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x8x8xf32>

  // MaxPool2d with kernel=2, stride=2, no padding
  // Use reduce_window with maximum
  %init_max = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf for max init
  %maxpool = "stablehlo.reduce_window"(%conv_bias, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

  // Hardtanh activation clamp between -1 and 1
  %const_neg1 = stablehlo.constant dense<-1.0> : tensor<f32>
  %const_1 = stablehlo.constant dense<1.0> : tensor<f32>
  %max_neg1 = stablehlo.maximum %maxpool, %const_neg1 : tensor<6x7x4x4xf32>
  %hardtanh = stablehlo.minimum %max_neg1, %const_1 : tensor<6x7x4x4xf32>

  // Mean over spatial dims (2,3) keepdim=True
  // sum over dims 2 and 3
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%hardtanh, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %s : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Divide by 16 (4*4) to get mean
  %const_16 = stablehlo.constant dense<16.0> : tensor<f32>
  %const_16_bcast = "stablehlo.broadcast_in_dim"(%const_16) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %mean = stablehlo.divide %sum, %const_16_bcast : tensor<6x7xf32>

  // Reshape mean to keep dims (6x7x1x1)
  %mean_reshaped = stablehlo.reshape %mean : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Tanh activation
  %tanh = stablehlo.tanh %mean_reshaped : tensor<6x7x1x1xf32>

  return %tanh : tensor<6x7x1x1xf32>
}
