func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x8x8xf32>) -> tensor<6x7x1x1xf32> {
  // %arg0: conv_transpose.weight with shape [out_channels=7, in_channels=7, kernel_h=3, kernel_w=3]
  // %arg1: conv_transpose.bias with shape [out_channels=7]
  // %arg2: input tensor with shape [batch=6, in_channels=7, height=8, width=8]

  // Step 1: ConvTranspose2d (transposed convolution)
  // ConvTranspose2d is a backward convolution with respect to input.
  // We implement it as a convolution with lhs and rhs swapped and appropriate dimension_numbers.
  // PyTorch ConvTranspose2d parameters:
  // stride=1, padding=1
  // Input shape: [6, 7, 8, 8]
  // Weight shape: [7, 7, 3, 3] (out_channels, in_channels, kernel_h, kernel_w)
  // Output shape: [6, 7, 8, 8] (batch, out_channels, H_out, W_out)
  //
  // StableHLO convolution dimension_numbers:
  // lhs: [batch, feature, spatial...]
  // rhs: [out_feature, in_feature, spatial...]
  // output: [batch, feature, spatial...]
  //
  // For transposed convolution, we swap lhs and rhs roles and use rhs_dilation = stride.
  // But since stride=1, rhs_dilation=1, so we can use convolution with lhs_dilation=1, rhs_dilation=1.
  //
  // We use dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 0, 1]->[b, o, 2, 3]>
  // where b=batch, i=in_channels, o=out_channels, 2 and 3 are spatial dims.
  //
  // To implement ConvTranspose2d with stride=1, padding=1:
  // We use lhs = input (%arg2) shape [6,7,8,8]
  // rhs = weight (%arg0) shape [7,7,3,3]
  // We swap lhs and rhs and use lhs_dilation = stride = 1, rhs_dilation = 1
  //
  // But StableHLO convolution does not directly support transposed convolution.
  // The standard way is to use convolution with lhs = input, rhs = weight, but with lhs_dilation = stride and padding adjusted.
  //
  // For stride=1, padding=1, lhs_dilation=1, so we can do normal convolution with weight flipped spatially.
  //
  // However, PyTorch ConvTranspose2d does not flip kernel spatially.
  //
  // So we implement ConvTranspose2d as convolution with:
  // lhs = input
  // rhs = weight flipped spatially (kernel_h and kernel_w dims reversed)
  // window_strides = 1
  // padding = padding for transposed convolution:
  // output_size = (input_size - 1) * stride - 2*padding + kernel_size + output_padding
  // For stride=1, padding=1, output_padding=0:
  // output_size = input_size - 2 + 3 = input_size + 1
  //
  // But input and output spatial dims are both 8, so output_padding = 0, output size = 8
  //
  // So we do convolution with padding=1, stride=1, kernel flipped spatially.
  //
  // We flip kernel spatially by reversing dims 2 and 3 of %arg0.

  // Reverse kernel spatial dims 2 and 3
  %reversed_kernel_1 = stablehlo.reverse %arg0 : tensor<7x7x3x3xf32> dimensions = [2]
  %reversed_kernel = stablehlo.reverse %reversed_kernel_1 : tensor<7x7x3x3xf32> dimensions = [3]

  // Perform convolution
  %conv = stablehlo.convolution %arg2, %reversed_kernel {
    window_strides = [1, 1],
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = [1, 1],
    rhs_dilation = [1, 1],
    dimension_numbers = #conv_dim_numbers,
    feature_group_count = 1,
    batch_group_count = 1
  } : (tensor<6x7x8x8xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x8x8xf32>

  // Add bias: broadcast bias %arg1 [7] to [6,7,8,8]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x8x8xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x8x8xf32>

  // Step 2: MaxPool2d with kernel_size=2, stride=2
  // Use reduce_window with maximum reduction
  %init_max = stablehlo.constant dense[-inf] : tensor<f32>
  %maxpool = stablehlo.reduce_window %conv_bias, %init_max {
    window_dimensions = [1, 1, 2, 2],
    window_strides = [1, 1, 2, 2],
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

  // Step 3: Hardtanh activation clamp between -1 and 1
  %min_val = stablehlo.constant dense[-1.0] : tensor<f32>
  %max_val = stablehlo.constant dense[1.0] : tensor<f32>
  %clamped_min = stablehlo.maximum %maxpool, %min_val : tensor<6x7x4x4xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val : tensor<6x7x4x4xf32>

  // Step 4: Mean over spatial dims (2,3) with keepdim=True
  // Use reduce with add and then divide by 16 (4*4)
  %init_zero = stablehlo.constant dense[0.0] : tensor<f32>
  %sum = stablehlo.reduce %hardtanh, %init_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } {dimensions = [2, 3]} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Reshape sum to keep dims: [6,7,1,1]
  %sum_reshaped = stablehlo.reshape %sum : tensor<6x7xf32> to tensor<6x7x1x1xf32>

  // Divide by 16.0 (4*4)
  %divisor = stablehlo.constant dense[16.0] : tensor<f32>
  %divisor_broadcast = stablehlo.broadcast_in_dim %divisor : tensor<f32> to tensor<6x7x1x1xf32> broadcast_dimensions = []
  %mean = stablehlo.divide %sum_reshaped, %divisor_broadcast : tensor<6x7x1x1xf32>

  // Step 5: Tanh activation
  %output = stablehlo.tanh %mean : tensor<6x7x1x1xf32>

  func.return %output : tensor<6x7x1x1xf32>
}

// Define convolution dimension numbers attribute
// lhs: [batch, in_feature, height, width] = [b, i, 2, 3]
// rhs: [out_feature, in_feature, kernel_h, kernel_w] = [o, i, 0, 1]
// output: [batch, out_feature, height, width] = [b, o, 2, 3]
#conv_dim_numbers = {
  lhs_batch_dimension = 0,
  lhs_feature_dimension = 1,
  lhs_spatial_dimensions = [2, 3],
  rhs_output_feature_dimension = 0,
  rhs_input_feature_dimension = 1,
  rhs_spatial_dimensions = [2, 3],
  output_batch_dimension = 0,
  output_feature_dimension = 1,
  output_spatial_dimensions = [2, 3]
}
