  %divisor = stablehlo.constant dense<16.0> : tensor<f32>
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %mean = stablehlo.divide %mean_reshaped, %divisor_broadcast : tensor<6x7x1x1xf32>

  // Step 5: Tanh activation
  %out = stablehlo.tanh %mean : tensor<6x7x1x1xf32>

  return %out : tensor<6x7x1x1xf32>
}
