func.func @main(%bmm_weight: tensor<7x7xf32>, %bmm_bias: tensor<7xf32>, %x: tensor<6x7xf32>, %y: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: x @ bmm_weight^T + bmm_bias
  // bmm_weight shape: [7,7], we need to transpose it to [7,7] (same shape, but transpose dims)
  %bmm_weight_t = "stablehlo.transpose"(%bmm_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: batch dims = [0], contract dims = [1] (x: [6x7], weight_t: [7x7])
  %linear = "stablehlo.dot_general"(%x, %bmm_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %linear_bias = stablehlo.add %linear, %bmm_bias : tensor<6x7xf32>

  // InstanceNorm2d on x after unsqueeze(1).unsqueeze(1)
  // Input to instance norm: shape [6, 7, 1, 1]
  %linear_4d = "stablehlo.reshape"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Compute mean over spatial dims (2,3) for each batch and channel
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%linear_4d, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
  // mean = sum / (1*1) = sum (no division needed)

  // Compute variance: mean of squared difference
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  %diff = stablehlo.subtract %linear_4d, %mean_broadcast : tensor<6x7x1x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x1x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
  // var = sum / (1*1) = sum (no division needed)

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<6x7xf32>

  // sqrt(var + eps)
  %std = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Broadcast std to 4D
  %std_broadcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Normalize: (x - mean) / std
