func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bmm.weight (7x7)
  // %arg1 = bmm.bias (7)
  // %arg2 = input x (6x7)
  // %arg3 = input y (6x7)

  // Linear layer: x = x @ weight^T + bias
  // We need to do batch matmul of (6x7) with (7x7) weight transposed to (7x7)
  // But weight is (7x7), so we do dot_general with contracting dims [1] and [0]
  // batch dims: [0] for x and y (batch size 6)
  // x shape: [6,7], weight shape: [7,7]
  // We want output shape: [6,7]

  // Reshape %arg2 to [6,1,7] to treat batch dim 0 and feature dim 2 for dot_general
  %x_reshaped = "stablehlo.reshape"(%arg2) : (tensor<6x7xf32>) -> tensor<6x1x7xf32>

  // Reshape weight to [1,7,7] to broadcast batch dim 0
  %weight_reshaped = "stablehlo.reshape"(%arg0) : (tensor<7x7xf32>) -> tensor<1x7x7xf32>

  // Broadcast weight to [6,7,7]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%weight_reshaped) {broadcast_dimensions = array<i64: 1, 2>} : (tensor<1x7x7xf32>) -> tensor<6x7x7xf32>

  // Perform dot_general:
  // lhs: %x_reshaped [6x1x7]
  // rhs: %weight_broadcast [6x7x7]
  // batch dims: [0]
  // contracting dims: lhs [2], rhs [1]
  %bmm = "stablehlo.dot_general"(%x_reshaped, %weight_broadcast) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [0], lhs_contracting_dimensions = [2], rhs_contracting_dimensions = [1]>} : (tensor<6x1x7xf32>, tensor<6x7x7xf32>) -> tensor<6x1x7xf32>

  // Remove the middle dimension: reshape from [6x1x7] to [6x7]
  %bmm_reshaped = "stablehlo.reshape"(%bmm) : (tensor<6x1x7xf32>) -> tensor<6x7xf32>

  // Add bias: %arg1 shape is [7], broadcast to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %bmm_bias = "stablehlo.elementwise.add"(%bmm_reshaped, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // InstanceNorm2d with eps=1e-5, momentum=0.1 on output channels=7
  // Input shape for instance norm: (N, C, H, W) = (6,7,1,1)
  // So reshape %bmm_bias from [6x7] to [6x7x1x1]
  %bmm_bias_reshaped = "stablehlo.reshape"(%bmm_bias) : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Compute mean over spatial dims (2,3) for each instance and channel
  // mean = reduce sum / (1*1) = sum over dims 2 and 3
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0,1>} : (tensor<f32>) -> tensor<6x7xf32>
  %sum_spatial = "stablehlo.reduce"(%bmm_bias_reshaped, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.elementwise.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // mean = sum_spatial / 1 (since spatial dims are 1x1)
  // So mean = sum_spatial
  %mean = %sum_spatial

  // Compute variance: mean of (x - mean)^2 over spatial dims
  // First broadcast mean to shape [6x7x1x1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // x - mean
  %diff = "stablehlo.elementwise.subtract"(%bmm_bias_reshaped, %mean_broadcast) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // (x - mean)^2
  %diff_sq = "stablehlo.elementwise.multiply"(%diff, %diff) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // Reduce sum over spatial dims (2,3)
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0,1>} : (tensor<f32>) -> tensor<6x7xf32>
  %sum_var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add2 = "stablehlo.elementwise.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // variance = sum_var / 1 = sum_var
  %variance = %sum_var

  // eps constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // variance + eps
  %var_eps = "stablehlo.elementwise.add"(%variance, %eps) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // sqrt(variance + eps)
  %stddev = "stablehlo.elementwise.sqrt"(%var_eps) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  // Broadcast stddev to [6x7x1x1]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0,1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  %normalized = "stablehlo.elementwise.divide"(%diff, %stddev_broadcast) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // Reshape normalized output back to [6x7]
  %normalized_reshaped = "stablehlo.reshape"(%normalized) : (tensor<6x7x1x1xf32>) -> tensor<6x7xf32>

  // x = normalized output

  // x + y
  %add_xy = "stablehlo.elementwise.add"(%normalized_reshaped, %arg3) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // x * y
  %mul_xy = "stablehlo.elementwise.multiply"(%add_xy, %arg3) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %mul_xy : tensor

