func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Perform linear transformation: x * W^T + b
  // %arg0 is weight matrix of shape [7,7] (out_features x in_features)
  // %arg2 is input of shape [6,7] (batch_size x in_features)
  // We want to do: output = %arg2 * %arg0^T + %arg1
  // So transpose %arg0 to [7,7] (actually same shape, but we treat it as W^T)
  // Actually, PyTorch Linear does x * W^T + b, so we do dot_general with contracting dims [1] and [1] and batch dims [0]
  // But input is [6,7], weight is [7,7], so to do x * W^T, we do dot_general with lhs_contracting_dims=[1], rhs_contracting_dims=[1], rhs is transposed weight

  // Transpose weight to get W^T
  %weight_t = stablehlo.transpose %arg0 {permutation = dense<[1,0]> : tensor<2xi64>} : tensor<7x7xf32> -> tensor<7x7xf32>

  // Dot general: batch dims empty, contracting dims lhs=1, rhs=0
  %dot = stablehlo.dot_general %arg2, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Broadcast bias %arg1 from [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<7xf32> -> tensor<6x7xf32>

  // Add bias
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Define Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // We use math.exponential, math.log_plus_one, math.tanh

  // First Mish application
  %exp1 = stablehlo.exponential %linear_out : tensor<6x7xf32>
  %softplus1 = stablehlo.log_plus_one %exp1 : tensor<6x7xf32>
  %tanh1 = stablehlo.tanh %softplus1 : tensor<6x7xf32>
  %mish1 = stablehlo.multiply %linear_out, %tanh1 : tensor<6x7xf32>

  // Second Mish application
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7xf32>
  %softplus2 = stablehlo.log_plus_one %exp2 : tensor<6x7xf32>
  %tanh2 = stablehlo.tanh %softplus2 : tensor<6x7xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh2 : tensor<6x7xf32>

  // Return final output
  return %mish2 : tensor<6x7xf32>
}
