  // dimension_numbers: input [b, f, d, h, w], kernel [o, i, kd, kh, kw], output [b, f, d, h, w]
  // feature_group_count = 1, batch_group_count = 1
  %conv = stablehlo.convolution %arg3, %weight_transposed {
    window_strides = [1, 1, 1],
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = [2, 2, 2],
    rhs_dilation = [1, 1, 1],
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1,
    batch_group_count = 1
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Step 3: add conv bias %arg2 (shape 16) broadcasted to conv output shape
  %conv_bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x31x13x13xf32> broadcast_dimensions = [1]
  %conv_biased = stablehlo.add %conv, %conv_bias_broadcast : tensor<6x16x31x13x13xf32>

  // Step 4: logsumexp over channel dimension (dim=1), keepdim = true
  // logsumexp(x) = log(sum(exp(x), dim))
  // Compute exp
  %exp_conv = stablehlo.exponential %conv_biased : tensor<6x16x31x13x13xf32>
  // sum over dim=1 (channels)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce %exp_conv, %init_zero (
