      stablehlo.return %add : tensor<f32>
  ) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // log of sum
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1x31x13x13xf32>

