  // sigmoid(x) = 1/(1+exp(-x))
  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = stablehlo.broadcast_in_dim %three : tensor<f32> to tensor<6x1x31x13x13xf32> broadcast_dimensions = []
  %x_plus_3 = stablehlo.add %log_sum_exp, %three_broadcast : tensor<6x1x31x13x13xf32>
