  %six_broadcast = stablehlo.broadcast_in_dim %six : tensor<f32> to tensor<6x1x31x13x13xf32> broadcast_dimensions = []
  %hard_swish = stablehlo.divide %mul_x_sigmoid, %six_broadcast : tensor<6x1x31x13x13xf32>

