  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<1x1x1x1xf32> to tensor<6x1x31x13x13xf32> broadcast_dimensions = [1, 2, 3, 4]
  %sub = stablehlo.subtract %hard_swish, %bias_broadcast : tensor<6x1x31x13x13xf32>

