  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = stablehlo.broadcast_in_dim %neg_one : tensor<f32> to tensor<6x1x31x13x13xf32> broadcast_dimensions = []
