  %clamp_min = stablehlo.maximum %sub, %neg_one_broadcast : tensor<6x1x31x13x13xf32>
  %clamp = stablehlo.minimum %clamp_min, %one_broadcast2 : tensor<6x1x31x13x13xf32>

