  // AvgPool1d is reduce_window with window_dimensions=[1,1,16], strides=[1,1,16], init=0, and sum reduction, then divide by kernel size
  // We do reduce_window sum over last dim with window size 16 and stride 16

  // Create zero init scalar
  %zero = stablehlo.constant 0.0 : tensor<f32>

  // Define sum reduction body
  %sum_body = () -> (tensor<f32>) {
    %a = block.argument 0 : tensor<f32>
    %b = block.argument 1 : tensor<f32>
    %c = stablehlo.add %a, %b : tensor<f32>
    stablehlo.return %c : tensor<f32>
  }

  %sum_pool = stablehlo.reduce_window %matmul_bias_3d, %zero
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> = {
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
      }
    })
    {
      window_dimensions = dense<[1, 1, 16]> : tensor<3xi64>,
      window_strides = dense<[1, 1, 16]> : tensor<3xi64>,
      padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>
    } : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1x1xf32>

  // Divide by kernel size (16) to get average
  %kernel_size = stablehlo.constant 16.0 : tensor<f32>
  %kernel_size_bcast = stablehlo.broadcast_in_dim %kernel_size
    {broadcast_dimensions = dense<[]> : tensor<0xi64>} : tensor<f32> -> tensor<16x1x1xf32>

  %avg_pool = stablehlo.divide %sum_pool, %kernel_size_bcast : tensor<16x1x1xf32>

  // Remove channel dim: reshape (16x1x1) -> (16x1)
  %avg_pool_2d = stablehlo.reshape %avg_pool : tensor<16x1x1xf32> -> tensor<16x1xf32>

  // Remove last dim: reshape (16x1) -> (16)
  %avg_pool_1d = stablehlo.reshape %avg_pool_2d : tensor<16x1xf32> -> tensor<16xf32>

  // 3) GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
