  // Broadcast weight and bias to [8,8,10,10]
  %weight_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<8xf32> to tensor<8x8x10x10xf32> broadcast_dimensions = [1]
  %bias_broadcast2 = stablehlo.broadcast_in_dim %arg3 : tensor<8xf32> to tensor<8x8x10x10xf32> broadcast_dimensions = [1]

