  %window_dims = stablehlo.concatenate [ %c1, %c1, %c16 ] : tensor<i64> x 3 -> tensor<3xi64>
  %window_strides = stablehlo.concatenate [ %c1, %c1, %c16 ] : tensor<i64> x 3 -> tensor<3xi64>

