  // Instead of transpose, we swap contracting dims accordingly:
  // Contract lhs dim 1 with rhs dim 0 to get (16x16) * (16x16) -> (16x16)
  // So we do dot_general with lhs_contracting_dims=[1], rhs_contracting_dims=[0]
