func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // SELU activation: x -> scale * (x if x > 0 else alpha * (exp(x) - 1))
  // Constants for SELU (from the original paper):
  // scale = 1.0507009873554804934193349852946
  // alpha = 1.6732632423543772848170429916717

  %c_scale = stablehlo.constant dense<1.0507009> : tensor<f32>
  %c_alpha = stablehlo.constant dense<1.6732632> : tensor<f32>
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Broadcast constants to input shape
  %scale = stablehlo.broadcast_in_dim %c_scale : tensor<f32> to tensor<6x7xf32> dimensions=[]
  %alpha = stablehlo.broadcast_in_dim %c_alpha : tensor<f32> to tensor<6x7xf32> dimensions=[]
  %zero = stablehlo.broadcast_in_dim %c_zero : tensor<f32> to tensor<6x7xf32> dimensions=[]

  // Compare input > 0
  %pos_mask = stablehlo.compare "gt" %arg0, %zero : tensor<6x7xf32>

  // Compute exp(x) - 1
  %exp_x = stablehlo.exponential %arg0 : tensor<6x7xf32>
  %exp_minus_one = stablehlo.subtract %exp_x, %scale : tensor<6x7xf32>  // temporary, will fix below

  // Correction: exp_minus_one = exp(x) - 1, so subtract 1, not scale
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_b = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> dimensions=[]
  %exp_minus_one = stablehlo.subtract %exp_x, %one_b : tensor<6x7xf32>

  // alpha * (exp(x) - 1)
  %alpha_times = stablehlo.multiply %alpha, %exp_minus_one : tensor<6x7xf32>

  // Select x if x > 0 else alpha * (exp(x) - 1)
  %selu_inner = stablehlo.select %pos_mask, %arg0, %alpha_times : tensor<6x7xf32>

  // scale * selu_inner
  %result = stablehlo.multiply %scale, %selu_inner : tensor<6x7xf32>

  func.return %result : tensor<6x7xf32>
}
