  // Compute the Frobenius norm of the input tensor %arg0.
  // Frobenius norm is sqrt of sum of squares of all elements.
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %init = stablehlo.broadcast_in_dim %cst_0 : tensor<f32> to tensor<f32>

  // Square the input elementwise
  %squared = stablehlo.multiply %arg0, %arg0 : tensor<6x7x8x8xf32>

  // Reduce sum over all dimensions [0,1,2,3]
  %sum = stablehlo.reduce(%squared, %cst_0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = dense<0 1 2 3> : tensor<4xi64>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<f32>

  // Compute sqrt of sum to get Frobenius norm
  %norm = stablehlo.sqrt %sum : tensor<f32>

  // Broadcast norm to input shape for division
  %norm_broadcast = stablehlo.broadcast_in_dim %norm 
    {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x7x8x8xf32>

  // Divide input by norm elementwise
  %result = stablehlo.divide %arg0, %norm_broadcast : tensor<6x7x8x8xf32>

  return %result : tensor<6x7x8x8xf32>
}
