  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Divide exp_conv by sum_exp_bcast
  %softmax = stablehlo.divide %exp_conv, %sum_exp_bcast : tensor<6x6x15x15xf32>

