  // Broadcast bias to [6,6,15,15]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>

  %add_bias = stablehlo.add %softmax, %bias_bcast : tensor<6x6x15x15xf32>

