  // weight shape: [7,7], input: [6,7]
  // We want to do input * weight^T, so transpose weight
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %x1 = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %x2 = "stablehlo.add"(%x1, %bias) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

  // %x3 = x2 * scale (broadcast scale from [7] to [6x7])
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x3 = "stablehlo.multiply"(%x2, %scale_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // Compute mean over batch dimension (dim=0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x3, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_scaled = "stablehlo.divide"(%mean, %six_broadcast) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Compute variance over batch dimension (dim=0)
  // variance = mean((x - mean)^2)
  // Broadcast mean to [6x7]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_minus_mean = "stablehlo.subtract"(%x3, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %sq = "stablehlo.multiply"(%x_minus_mean, %x_minus_mean) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = "stablehlo.divide"(%var_sum, %six_broadcast) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>

