  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<7xf32>) -> tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_centered = "stablehlo.subtract"(%x3, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %x_norm = "stablehlo.divide"(%x_centered, %stddev_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

