  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]
  // %arg0: multiply_weight, shape [16]

  // GEMM: x @ W^T + bias
  // Note: PyTorch Linear weight shape is [out_features, in_features], so we transpose %arg1 to get [in_features, out_features]
  // But here %arg1 is [16x16], we want to do x @ W^T, so we do dot_general with contracting dims [1] of x and [1] of W, batching dims empty.
  // Actually, PyTorch Linear does x @ W^T + b, so we do dot_general with lhs_contracting=1, rhs_contracting=1, rhs is weight, so we must transpose weight to get W^T.
  // So we transpose %arg1 from [16x16] to [16x16] swapping dims 0 and 1.
  %w_t = stablehlo.transpose %arg1 {permutation = dense<[1, 0]>} : tensor<16x16xf32> -> tensor<16x16xf32>
  %gemm = stablehlo.dot_general %arg5, %w_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias [16] to [16x16] on dim 1
  %bias_bcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_bcast : tensor<16x16xf32>

  // GroupNorm:
  // GroupNorm with num_groups=16, out_features=16, so each group has 1 channel.
  // Input shape: [N=16, C=16]
  // Reshape to [N=16, G=16, C_per_group=1]
  %reshape1 = stablehlo.reshape %gemm_bias : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over C_per_group dim=2
  %zero = stablehlo.constant 0.0 : tensor<f32>
  %mean = stablehlo.reduce %reshape1, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[2]>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16,16], divide by 1 (C_per_group=1), so mean = sum
  // So no division needed.

  // Compute (x - mean)
  // Broadcast mean from [16,16] to [16,16,1]
  %mean_bcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = dense<[0,1]>} : tensor<16x16xf32> -> tensor<16x16x1xf32>
  %x_centered = stablehlo.subtract %reshape1, %mean_bcast : tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over dim=2
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16x1xf32>
  %var = stablehlo.reduce %x_centered_sq, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[2]>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance shape: [16,16], divide by 1 (C_per_group=1), so var = sum
  // No division needed.

  // Add epsilon for numerical stability
  %eps = stablehlo.constant 1.0e-5 : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = dense<[]>} : tensor<f32> -> tensor<f32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std : tensor<16x16x1xf32>

  // Reshape back to [16,16]
  %x_norm_2d = stablehlo.reshape %x_norm : tensor<16x16x1xf32> -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape [16])
  // Broadcast weight and bias to [16x16] along dim 1
  %gn_weight_bcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %gn_bias_bcast = stablehlo.broadcast_in_dim %arg4 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>

  // Multiply normalized x by weight and add bias
  %x_scaled = stablehlo.multiply %x_norm_2d, %gn_weight_bcast : tensor<16x16xf32>
  %x_shifted = stablehlo.add %x_scaled, %gn_bias_bcast : tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x_shifted : tensor<16x16xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<16x16xf32>
  %one = stablehlo.constant 1.0 : tensor<f32>
  %one_bcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = dense<[]>} : tensor<f32> -> tensor<f32>
  %denom = stablehlo.add %one_bcast, %exp_neg_x : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %x_shifted, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]), broadcast to [16x16] along dim 1
  %mul_weight_bcast = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %mul = stablehlo.multiply %swish1, %mul_weight_bcast : tensor<16x16xf32>

  // Second Swish activation: mul * sigmoid(mul)
  %neg_mul = stablehlo.negate %mul : tensor<16x16xf32>
  %exp_neg_mul = stablehlo.exponential %neg_mul : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_bcast, %exp_neg_mul : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %mul, %sigmoid2 : tensor<16x16xf32>

  func.return %swish2 : tensor<16x16xf32>
}
