  // gemm.weight shape is (16x16), input is (16x16)
  // We want input (16x16) * weight^T (16x16) -> (16x16)
  // So transpose weight to (16x16) (actually same shape, but transpose swaps dims)
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %gemm_dot = "stablehlo.dot_general"(%arg5, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %gemm_out = stablehlo.add %gemm_dot, %arg2 : tensor<16x16xf32>  // broadcast bias over dim0

  // GroupNorm:
  // num_groups = 16, out_features = 16, so each group has 1 channel
  // GroupNorm normalizes over group channels and spatial dims.
  // Here input shape is (batch=16, channels=16)
  // GroupNorm with 16 groups means each channel is its own group.
  // So mean and variance are computed per channel over batch dimension.
  // Compute mean over batch dim (dim 0)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %mean = "stablehlo.reduce"(%gemm_out, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16xf32>
  // mean = sum over batch dim, shape (16)
  // divide by batch_size=16
  %batch_size = stablehlo.constant dense<16.0> : tensor<f32>
  %mean_f32 = stablehlo.divide %mean, %batch_size : tensor<16xf32>

  // Broadcast mean to shape (16x16) for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_f32) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %gemm_out, %mean_bcast : tensor<16x16xf32>

  // Compute variance: mean of squared differences
  %squared = stablehlo.multiply %x_centered, %x_centered : tensor<16x16xf32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %var_sum = "stablehlo.reduce"(%squared, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16xf32>
  %var = stablehlo.divide %var_sum, %batch_size : tensor<16xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<16xf32>

