  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast : tensor<16x16xf32>

  // Apply affine transform: weight * x_norm + bias
  // group_norm.weight and bias are (16), broadcast to (16x16)
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %x_norm, %weight_bcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_bcast : tensor<16x16xf32>

