func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: %arg2 (6x7) * %arg0^T (7x7) + %arg1 (7)
  // Note: %arg0 is weight of shape (7x7), input_size=7, hidden_size=7
  // PyTorch Linear does x @ W^T + b, so we do dot_general with lhs=%arg2, rhs=%arg0, contracting dim 1 of lhs and dim 1 of rhs (rhs is not transposed here, so we transpose it)
  %0 = stablehlo.transpose %arg0 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}
  %1 = stablehlo.dot_general %arg2, %0 : tensor<6x7xf32>, tensor<7x7xf32> 
    -> tensor<6x7xf32> {
      lhs_batching_dims = [],
      rhs_batching_dims = [],
      lhs_contracting_dims = [1],
      rhs_contracting_dims = [0]
    }
  // Add bias: broadcast bias %arg1 (7) to (6x7)
  %2 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>
  // Apply sigmoid elementwise: sigmoid(x) = 1 / (1 + exp(-x))
  %4 = stablehlo.negate %3 : tensor<6x7xf32>
  %5 = stablehlo.exponential %4 : tensor<6x7xf32>
  %6 = stablehlo.add %5, %cst_1 : tensor<6x7xf32>
  %7 = stablehlo.divide %cst_1, %6 : tensor<6x7xf32>
  // Reduce sum along dim=1, keepdim=1 -> output shape (6x1)
  %8 = stablehlo.reduce %7, %cst_0 : tensor<6x7xf32>, tensor<f32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %9 = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %9 : tensor<f32>
  } dimensions = [1]
  return %8 : tensor<6x1xf32>
}

