  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]
  // %arg0: multiply_weight, shape [16]

  // GEMM: x @ weight^T + bias
  // dot_general with batch dims [0] and contracting dims [1]
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias [16] to [16,16] on dim 1
  %1 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, so each group has 1 channel (C=16)
  // Reshape [16,16] -> [16,16,1] to have group dim
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group channels dim=2 (size=1), so mean = x itself
  // But to follow general formula, do reduce over dim=2
  %4 = stablehlo.reduce %3, %cst0 = stablehlo.constant dense<0.0> : tensor<f32> {
    dimensions = [2],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = %4 / 1 = %4
  // Compute variance = mean((x - mean)^2)
  // Subtract mean broadcasted to dim=2
  %5 = stablehlo.broadcast_in_dim %4 : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]
  %6 = stablehlo.subtract %3, %5 : tensor<16x16x1xf32>

  %7 = stablehlo.multiply %6, %6 : tensor<16x16x1xf32>

  %8 = stablehlo.reduce %7, %cst0 : tensor<f32> {
    dimensions = [2],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = %8 / 1 = %8
  // epsilon = 1e-5
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %9 = stablehlo.add %8, %c_eps : tensor<16x16xf32>

  // rsqrt(variance + eps)
  %10 = stablehlo.rsqrt %9 : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %11 = stablehlo.multiply %6, stablehlo.broadcast_in_dim %10 : tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  // Reshape back to [16,16]
  %12 = stablehlo.reshape %11 : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: y = weight * normalized + bias
  // Broadcast weight and bias from [16] to [16,16] on dim=1
  %13 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %14 = stablehlo.multiply %12, %13 : tensor<16x16xf32>
  %15 = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %16 = stablehlo.add %14, %15 : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %17 = stablehlo.negate %16 : tensor<16x16xf32>
  %18 = stablehlo.exp %17 : tensor<16x16xf32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %19 = stablehlo.broadcast_in_dim %c1 : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %20 = stablehlo.add %19, %18 : tensor<16x16xf32>
  %21 = stablehlo.divide %19, %20 : tensor<16x16xf32>
  %22 = stablehlo.multiply %16, %21 : tensor<16x16xf32>

  // Multiply by multiply_weight: broadcast multiply_weight [16] to [16,16] on dim=1
  %23 = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %24 = stablehlo.multiply %22, %23 : tensor<16x16xf32>

  // Swish again
  %25 = stablehlo.negate %24 : tensor<16x16xf32>
  %26 = stablehlo.exp %25 : tensor<16x16xf32>
  %27 = stablehlo.add %19, %26 : tensor<16x16xf32>
  %28 = stablehlo.divide %19, %27 : tensor<16x16xf32>
  %29 = stablehlo.multiply %24, %28 : tensor<16x16xf32>

  func.return %29 : tensor<16x16xf32>
}
