  // input: (6x7), weight: (7x7)
  // We want to do input * weight^T, so weight^T is (7x7) (same shape)
  // But since weight is square, transpose is the same shape, but we must transpose dims 0 and 1
  %weight_t = stablehlo.transpose %arg0 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}

  // Dot general: batch matmul input (6x7) * weight_t (7x7) -> (6x7)
  %dot = stablehlo.dot_general %arg2, %weight_t {
    lhs_batch_dims = [],
    rhs_batch_dims = [],
    lhs_contracting_dims = [1],
