  %one_tensor = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_tensor, %exp_neg_x1 : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_tensor, %denom : tensor<16x16xf32>
  %swish = stablehlo.multiply %x1, %sigmoid : tensor<16x16xf32>

