  %norm = "stablehlo.multiply"(%diff, %inv_stddev_broadcast) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

  // Broadcast weight and bias to input shape [6,6,7,7]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Apply scale and shift: norm * weight + bias
  %scaled = "stablehlo.multiply"(%norm, %weight_broadcast) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>
  %out = "stablehlo.add"(%scaled, %bias_broadcast) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

  return %out : tensor<6x6x7x7xf32>
}
