func.func @main(%arg0: tensor<6xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // %arg0 = bn.weight (scale), shape: [6]
  // %arg1 = bn.bias, shape: [6]
  // %arg2 = input tensor, shape: [6, 6, 7, 7]

  // BatchNorm2d in training mode:
  // Compute mean and variance per feature channel over batch and spatial dims.
  // mean[c] = mean over batch, height, width of input[:, c, :, :]
  // variance[c] = variance over batch, height, width of input[:, c, :, :]
  // output = (input - mean) / sqrt(variance + eps) * weight + bias

  // Constants
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %eps = stablehlo.constant dense<1.00000001e-05> : tensor<f32>  // typical eps for BatchNorm

  // Compute mean over dims [0, 2, 3] (batch, height, width)
  // input shape: [6,6,7,7]
  // reduce dims: 0,2,3 -> result shape: [6] (feature dim)
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%arg2, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute divisor = batch_size * height * width = 6*7*7 = 294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %c294 : tensor<6xf32>

  // Broadcast mean to input shape for variance calculation and normalization
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  // Broadcast to [6,6,7,7]
  %mean_broadcast_full = "stablehlo.broadcast_in_dim"(%mean_broadcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x7x7xf32>

  // Compute (input - mean)
  %input_minus_mean = stablehlo.subtract %arg2, %mean_broadcast_full : tensor<6x6x7x7xf32>

  // Compute squared difference (input - mean)^2
  %sq_diff = stablehlo.multiply %input_minus_mean, %input_minus_mean : tensor<6x6x7x7xf32>

  // Compute variance sum over dims [0,2,3]
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%sq_diff, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // variance = var_sum / 294
  %var = stablehlo.divide %var_sum, %c294 : tensor<6xf32>

  // Add epsilon to variance for numerical stability
  %var_eps = stablehlo.add %var, %eps : tensor<6xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6xf32>

  // Broadcast inv_std to input shape
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %inv_std_broadcast_full = "stablehlo.broadcast_in_dim"(%inv_std_broadcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x7x7xf32>

  // Broadcast weight (%arg0) to input shape
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %weight_broadcast_full = "stablehlo.broadcast_in_dim"(%weight_broadcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x7x7xf32>

  // Broadcast bias (%arg1) to input shape
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x7x7xf32>

  // Normalize: (input - mean) * inv_std
  %normalized = stablehlo.multiply %input_minus_mean, %inv_std_broadcast_full : tensor<6x6x7x7xf32>

  // Scale: normalized * weight
  %scaled = stablehlo.multiply %normalized, %weight_broadcast_full : tensor<6x6x7x7xf32>

  // Shift: scaled + bias
  %output = stablehlo.add %scaled, %bias_broadcast_full : tensor<6x6x7x7xf32>

  return %output : tensor<6x6x7x7xf32>
}
