func.func @main(%weight: tensor<6xf32>, %bias: tensor<6xf32>, %x: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Compute mean over batch (dim 0), height (dim 2), width (dim 3)
  %c0 = stablehlo.constant dense<0> : index
  %c1 = stablehlo.constant dense<1> : index
  %c2 = stablehlo.constant dense<2> : index
  %c3 = stablehlo.constant dense<3> : index

  // Initial zero for mean reduction
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>

  // Reduce sum over dims 0,2,3 to get sum per feature (dim 1)
  %sum = "stablehlo.reduce"(%x, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<6xf32>) -> tensor<6xf32>

  // Compute divisor = batch_size * dim1 * dim2 = 6*7*7=294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>

  // mean = sum / 294
  %mean = stablehlo.divide %sum, %c294 : tensor<6xf32>

  // Broadcast mean to input shape for subtraction
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // x_centered = x - mean
  %x_centered = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>

  // Compute variance: mean of squared differences
  // square x_centered
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x7x7xf32>

  // Initial zero for variance reduction
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>

  // sum of squared diffs over dims 0,2,3
  %sum_sq = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<6xf32>) -> tensor<6xf32>

  // variance = sum_sq / 294
  %variance = stablehlo.divide %sum_sq, %c294 : tensor<6xf32>

  // epsilon = 1e-5
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  // variance + epsilon
  %var_eps = stablehlo.add %variance, %eps : tensor<6xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6xf32>

  // Broadcast stddev to input shape
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Normalize: x_centered / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast : tensor<6x6x7x7xf32>

  // Broadcast weight and bias to input shape
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%weight) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
