  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%c_divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  // Divide by divisor
  %div = stablehlo.divide %conv_bias, %divisor_broadcast : tensor<6x7x4x4xf32>

  // Create constant zero for LeakyReLU comparison
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

