  %leaky_relu = "stablehlo.select"(%cmp, %div, %mul_neg) : (tensor<6x7x4x4xi1>, tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

