  %cst_0_broadcast = stablehlo.broadcast_in_dim %cst_0 : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions=[]
  %max0 = stablehlo.maximum %add3, %cst_0_broadcast : tensor<6x6x4x4xf32>

