  %cst_6_broadcast = stablehlo.broadcast_in_dim %cst_6 : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions=[]
  %relu6 = stablehlo.minimum %max0, %cst_6_broadcast : tensor<6x6x4x4xf32>

  // multiply x * relu6(x+3)
  %mul = stablehlo.multiply %sub, %relu6 : tensor<6x6x4x4xf32>

  // divide by 6
  %div = stablehlo.divide %mul, %cst_6_broadcast : tensor<6x6x4x4xf32>

  // MaxPool2d with kernel=2, stride=2, no padding
  // input shape: [6,6,4,4]
  // output shape: [6,6,2,2]
  %pool = stablehlo.reduce_window %div {
    window_dimensions = [1, 1, 2, 2],
    window_strides = [1, 1, 2, 2],
    padding = [0, 0, 0, 0, 0, 0, 0, 0],
    base_dilation = [1, 1, 1, 1],
    window_dilation = [1, 1, 1, 1],
    // max pooling
    // init value = -inf
  } : tensor<6x6x4x4xf32> to tensor<6x6x2x2xf32> {
    body = (arg0: f32, arg1: f32) -> (f32) {
      %max = stablehlo.maximum %arg0, %arg1 : f32
      stablehlo.return %max : f32
    },
    init_value = -inf
  }

  // Mish activation: x * tanh(softplus(x)) = x * tanh(ln(1 + exp(x)))
  // softplus(x) = ln(1 + exp(x))
  // compute exp(pool)
  %exp_pool = stablehlo.exponential %pool : tensor<6x6x2x2xf32>

  // compute 1 + exp(pool)
  %cst_1 = stablehlo.constant 1.0 : f32
  %cst_1_broadcast = stablehlo.broadcast_in_dim %cst_1 : tensor<f32> to tensor<6x6x2x2xf32> broadcast_dimensions=[]
  %add1 = stablehlo.add %cst_1_broadcast, %exp_pool : tensor<6x6x2x2xf32>

  // compute ln(1 + exp(pool))
  %softplus = stablehlo.log %add1 : tensor<6x6x2x2xf32>

  // compute tanh(softplus)
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>

  // multiply pool * tanh(softplus)
  %mish = stablehlo.multiply %pool, %tanh_softplus : tensor<6x6x2x2xf32>

  stablehlo.return %mish : tensor<6x6x2x2xf32>
}
