  // stride=1, padding=0, dilation=1, groups=1 (default PyTorch conv2d)
  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw], output [b, f, oh, ow]
  // stablehlo convolution dimension_numbers format: [input_dims]x[kernel_dims]->[output_dims]
  // Here: input dims: b=0, f=1, h=2, w=3
  // kernel dims: o=0, i=1, kh=2, kw=3
  // output dims: b=0, f=1, oh=2, ow=3

  %zero = stablehlo.constant dense<0> : tensor<i64>
  %one = stablehlo.constant dense<1> : tensor<i64>

  // Convolution: no padding, stride 1, dilation 1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
