func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // Convolution: output shape [6, 6, 6, 6]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x6x6xf32>

  // Broadcast bias from [6] to [6,6,6,6] on dimension 1 (channels)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x1x1xf32>

  // Add bias to convolution output
  %conv_bias_added = stablehlo.add %conv, %bias_bcast : tensor<6x6x6x6xf32>

  // Subtract 0.5 (constant scalar) from conv output
  %c_sub = stablehlo.constant dense<0.5> : tensor<f32>
  %c_sub_bcast = "stablehlo.broadcast_in_dim"(%c_sub) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %sub = stablehlo.subtract %conv_bias_added, %c_sub_bcast : tensor<6x6x6x6xf32>

  // HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %c_3 = stablehlo.constant dense<3.0> : tensor<f32>
  %c_6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c_6_bcast = "stablehlo.broadcast_in_dim"(%c_6) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %c_3_bcast = "stablehlo.broadcast_in_dim"(%c_3) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>

  %x_plus_3 = stablehlo.add %sub, %c_3_bcast : tensor<6x6x6x6xf32>
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %max_0 = stablehlo.maximum %x_plus_3, %zero_bcast : tensor<6x6x6x6xf32>
  %relu6 = stablehlo.minimum %max_0, %c_6_bcast : tensor<6x6x6x6xf32>
  %mul = stablehlo.multiply %sub, %relu6 : tensor<6x6x6x6xf32>
  %c_6_inv = stablehlo.constant dense<0.16666667> : tensor<f32>  // 1/6
  %c_6_inv_bcast = "stablehlo.broadcast_in_dim"(%c_6_inv) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %hardswish = stablehlo.multiply %mul, %c_6_inv_bcast : tensor<6x6x6x6xf32>

  // MaxPool2d with kernel=2, stride=2, no padding
  // window_dimensions = [1,1,2,2] to cover batch, channel, height, width dims
  // window_strides = [1,1,2,2]
  %init = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf approx for max init
  %maxpool = "stablehlo.reduce_window"(%hardswish, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x6x6xf32>, tensor<f32>) -> tensor<6x6x3x3xf32>

  // Mish activation: x * tanh(ln(1 + exp(x)))
  %exp = stablehlo.exponential %maxpool : tensor<6x6x3x3xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x3x3xf32>
  %exp_plus_one = stablehlo.add %exp, %one_bcast : tensor<6x6x3x3xf32>
  %log = stablehlo.log %exp_plus_one : tensor<6x6x3x3xf32>
  %tanh = stablehlo.tanh %log : tensor<6x6x3x3xf32>
  %mish = stablehlo.multiply %maxpool, %tanh : tensor<6x6x3x3xf32>

  // Reshape output from [6,6,3,3] to [6,6,2,2]
  // The output shape is [6,6,2,2] as required by the signature.
  // The input has 6*6*3*3=324 elements, output 6*6*2*2=144 elements.
  // So we must slice or otherwise reduce spatial dims from 3x3 to 2x2.
  // The PyTorch MaxPool2d with kernel=2, stride=2 on 6x6 input produces 3x3 output.
  // The final output shape is 6x6x2x2, so we slice the last two dims to 2x2.

  // Slice last two dims from 3x3 to 2x2
  %start_indices = stablehlo.constant dense<[0, 0, 0, 0]> : tensor<4xi64>
  %limit_indices = stablehlo.constant dense<[6, 6, 2, 2]> : tensor<4xi64>
  %strides = stablehlo.constant dense<[1, 1, 1, 1]> : tensor<4xi64>
  %mish_reshaped = "stablehlo.slice"(%mish) {
    start_indices = dense<[0, 0, 0, 0]> : tensor<4xi64>,
    limit_indices = dense<[6, 6, 2, 2]> : tensor<4xi64>,
    strides = dense<[1, 1, 1, 1]> : tensor<4xi64>
  } : (tensor<6x6x3x3xf32>) -> tensor<6x6x2x2xf32>

  return %mish_reshaped : tensor<6x6x2x2xf32>
}
