func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x = input * weight^T + bias
  // weight is (7x7), input is (6x7)
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight needs to be transposed to (7x7) -> (7x7) (actually square, but we transpose to match PyTorch Linear)
  // PyTorch Linear does x @ weight.T + bias, so we transpose weight
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

