  // Normalize: (x - mean) / stddev
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>

  // Scale and shift: norm * weight + bias
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %norm, %weight_bcast : tensor<6x7xf32>
  %bias_bn_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %batch_norm_out = stablehlo.add %scaled, %bias_bn_bcast : tensor<6x7xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>  // approx sqrt(2)
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>

  // x / sqrt(2)
  %x_div_sqrt2 = stablehlo.divide %batch_norm_out, %sqrt2_bcast : tensor<6x7xf32>
  // erf(x / sqrt(2))
  %erf_val = chlo.erf %x_div_sqrt2 : tensor<6x7xf32> -> tensor<6x7xf32>
  // 1 + erf(...)
  %one_plus_erf = stablehlo.add %one_bcast, %erf_val : tensor<6x7xf32>
  // 0.5 * (1 + erf(...))
  %gelu_factor = stablehlo.multiply %half_bcast, %one_plus_erf : tensor<6x7xf32>
  // x * gelu_factor
  %gelu_out = stablehlo.multiply %batch_norm_out, %gelu_factor : tensor<6x7xf32>

  // ReLU: max(0, x)
  %zero_bcast = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast_6x7 = "stablehlo.broadcast_in_dim"(%zero_bcast) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %relu_out = stablehlo.maximum %gelu_out, %zero_bcast_6x7 : tensor<6x7xf32>

  "stablehlo.return"(%relu_out) : tensor<6x7xf32>
}
