  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []

  %relu = stablehlo.maximum %gelu, %zero_broadcast : tensor<6x7xf32>

  stablehlo.return %relu : tensor<6x7xf32>
}
