  // Note: PyTorch Linear does x @ W^T + b, so we do dot_general with contracting dims:
  // lhs: batch=0, features=1 (6x7)
  // rhs: weight is 7x7, but we want to contract rhs dim 1 (features) with lhs dim 1
  // So we do dot_general with lhs_contracting_dims=[1], rhs_contracting_dims=[1]
  // But arg0 is weight (7x7), we want to do x @ W^T, so we transpose arg0 first.

  %weight_t = stablehlo.transpose %arg0 {permutation = dense<[1, 0]>} : tensor<7x7xf32> -> tensor<7x7xf32>

  %gemm = stablehlo.dot_general %arg4, %weight_t
    {dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1
    {broadcast_dimensions = dense<[1]>} : tensor<7xf32> -> tensor<6x7xf32>

  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<6x7xf32>

  // BatchNorm in training mode:
  // y = gamma * ((x - mean) / sqrt(var + eps)) + beta
  // mean = reduce mean over batch dim (dim 0)
  // var = reduce variance over batch dim (dim 0)
  // eps = 1e-5 (typical default)

  // Compute mean over batch dim 0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = dense<[]>} : tensor<f32> -> tensor<7xf32>
  %mean = stablehlo.reduce %gemm_bias, %init_mean
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

