  %var = stablehlo.reduce %sq_diff, %init_var
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // var = var / 6
  %var_div = stablehlo.divide %var, %six : tensor<7xf32>

  // Broadcast var to (6x7)
  %var_broadcast = stablehlo.broadcast_in_dim %var_div {broadcast_dimensions = dense<[1]>} : tensor<7xf32> -> tensor<6x7xf32>

