  %var_eps = stablehlo.add %var_broadcast, %eps_broadcast_2d : tensor<6x7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev : tensor<6x7xf32>

