  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>  // sqrt(2)
  %sqrt2_broadcast = stablehlo.broadcast_in_dim %sqrt2 {broadcast_dimensions = dense<[]>} : tensor<f32> -> tensor<6x7xf32>

