  %zero_2d = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = dense<[]>} : tensor<f32> -> tensor<6x7xf32>
  %relu = stablehlo.maximum %gelu, %zero_2d : tensor<6x7xf32>

  func.return %relu : tensor<6x7xf32>
}
