      stablehlo.return %add : tensor<f32>
  }) {dimensions = dense<1> : tensor<1xi64>} : (tensor<6x16x16x6x6xf32>, tensor<f32>) -> tensor<6x1x16x6x6xf32>

  // Broadcast sum_exp to shape of exp for division
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = dense<0, 2, 3, 4>} : tensor<6x1x16x6x6xf32> -> tensor<6x16x16x6x6xf32>

  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x16x16x6x6xf32>

