  // %arg0 shape: [16]
  // Broadcast to [6,16,16,6,6]
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = dense<1>} : tensor<16xf32> -> tensor<6x16x16x6x6xf32>

