  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = dense<>} : tensor<f32> -> tensor<6x16x16x6x6xf32>
  %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<6x16x16x6x6xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x16x16x6x6xf32>
