  // - lhs = input tensor
  // - rhs = weight tensor reversed in spatial dims (depth, height, width)
  // - lhs_dilation = stride (3D stride = 1 here)
  // - rhs_dilation = 1 (no dilation)
  // - padding = 0 (no padding)
  // - dimension_numbers to map input/output dims correctly
  // - feature_group_count = 1 (no groups)
  //
  // The PyTorch ConvTranspose3d formula for output shape:
  // output_shape = (input_shape - 1) * stride - 2*padding + kernel_size + output_padding
  // Here stride=1, padding=0, output_padding=0, kernel_size=3
  // So output spatial dims = 7*1 - 0 + 3 + 0 = 9

  // Reverse the kernel spatial dimensions (3,4,5) to match transposed convolution semantics
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

