  // dimension_numbers: input [b, f, d, h, w], kernel [o, i, kd, kh, kw], output [b, f, d, h, w]
  // For transposed convolution, lhs_dilation = stride, rhs_dilation = 1
  %result = "stablehlo.convolution"(%arg1, %reversed_kernel) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
