  %avgpool = stablehlo.divide %avgpool_sum, %divisor_broadcast : tensor<6x7x1x1xf32>

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %avgpool : tensor<6x7x1x1xf32>
  %exp = stablehlo.exponential %neg : tensor<6x7x1x1xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %denom = stablehlo.add %one_broadcast, %exp : tensor<6x7x1x1xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x7x1x1xf32>

