      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6xf32>

  stablehlo.return %sum : tensor<6xf32>
}
