func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x8x8xf32>) -> tensor<6xf32> {
  // %arg0: conv.weight (out_channels=7, in_channels=8, kernel_h=3, kernel_w=3)
  // %arg1: conv.bias (out_channels=7)
  // %arg2: input tensor (batch=6, in_channels=8, height=8, width=8)

  // Convolution parameters:
  // PyTorch Conv2d default stride=1, padding=0, dilation=1, groups=1
  // Input shape: [6,8,8,8] (NCHW)
  // Weight shape: [7,8,3,3]
  // Output shape: [6,7,6,6] because (8-3+1)=6

  // Perform convolution
  %conv = stablehlo.convolution %arg2, %arg0 {
    window_strides = [1, 1],
    padding = [0, 0, 0, 0],
    lhs_dilate = [],
    rhs_dilate = [],
    feature_group_count = 1,
    batch_group_count = 1,
    dimension_numbers = #stablehlo.conv_dnums<lhs_batch=0 lhs_feature=1 lhs_spatial=(2, 3),
                                             rhs_out_feature=0 rhs_in_feature=1 rhs_spatial=(2, 3),
                                             out_batch=0 out_feature=1 out_spatial=(2, 3)>,
    precision_config = #stablehlo.default_precision_config
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6,7,6,6]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x6x6xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Average Pooling with kernel size 4x4, stride=4 (default for AvgPool2d)
  // Input shape: [6,7,6,6]
  // Pool kernel: 4x4
  // Stride: 4x4
  // Output shape: floor((6-4)/4)+1 = 1 for each spatial dim, so output shape [6,7,1,1]

  // Use reduce_window with add and divide by window size (16) to get average pooling

  // Define window dimensions: batch=1, feature=1, height=4, width=4
  // Strides: 1,1,4,4
  // Padding: 0

  %init = stablehlo.constant dense<0.0> : tensor<f32>

  %sum_pool = stablehlo.reduce_window %conv_bias, %init {
    window_dimensions = [1, 1, 4, 4],
    window_strides = [1, 1, 4, 4],
    padding = [0, 0, 0, 0, 0, 0, 0, 0]
  } : tensor<6x7x6x6xf32>, tensor<f32> -> tensor<6x7x1x1xf32> {
    region {
      %a = stablehlo.parameter 0 : f32
      %b = stablehlo.parameter 1 : f32
      %c = stablehlo.add %a, %b : f32
      stablehlo.return %c : f32
    }
  }

  // Divide by 16 (4*4) to get average
  %divisor = stablehlo.constant dense<16.0> : tensor<f32>
  %divisor_bcast = stablehlo.broadcast_in_dim %divisor : tensor<f32> to tensor<6x7x1x1xf32> broadcast_dimensions = []

  %avg_pool = stablehlo.divide %sum_pool, %divisor_bcast : tensor<6x7x1x1xf32>

  // Remove spatial dims (1,1) by reshape to [6,7]
  %avg_pool_reshaped = stablehlo.reshape %avg_pool : tensor<6x7x1x1xf32> to tensor<6x7xf32>

  // Apply sigmoid elementwise: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %avg_pool_reshaped : tensor<6x7xf32>
  %exp = stablehlo.exponential %neg : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_bcast, %exp : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<6x7xf32>

  // Sum over dimensions 1 (channels), 2 and 3 (spatial) of original output
  // Here after pooling and reshape, shape is [6,7], sum over dim=1
  %init_sum = stablehlo.constant dense<0.0> : tensor<f32>

  %sum = stablehlo.reduce %sigmoid, %init_sum {
    dimensions = [1]
  } : tensor<6x7xf32>, tensor<f32> -> tensor<6xf32> {
    region {
      %x = stablehlo.parameter 0 : f32
      %y = stablehlo.parameter 1 : f32
      %z = stablehlo.add %x, %y : f32
      stablehlo.return %z : f32
    }
  }

  stablehlo.return %sum : tensor<6xf32>
}
