func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0: gemm.weight (7x7)
  // %arg1: gemm.bias (7)
  // %arg2: input (6x7)

  // Compute gemm: x @ W^T + b
  // %arg0 is weight (out_features x in_features) = 7x7
  // %arg2 is input (batch_size x in_features) = 6x7
  // We want: (6x7) @ (7x7)^T = (6x7) @ (7x7) = (6x7)
  // So dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight is 7x7, we want to contract input dim 1 with weight dim 1 (the second dim)
  // Actually, weight is (out_features x in_features) = (7x7)
  // We want to do input (6x7) @ weight^T (7x7) = (6x7)
  // So dot_general contracting input dim 1 and weight dim 0 (to do input * weight^T)
  // So contract input dim 1 and weight dim 0, batch dims none
  // Result shape: (6x7)

  %0 = "stablehlo.dot_general"(%arg2, %arg0) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %1 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}

  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // max over dim=1 (max_dim=1), keepdim=True
  // stablehlo.reduce with max over dim=1, keepdim=True
  // reduce dims = [1]
  %3 = stablehlo.reduce %2, %cst_neg_inf : tensor<6x7xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.parameter 0 : tensor<f32>
      %b = stablehlo.parameter 1 : tensor<f32>
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // %3 shape is (6), but we want keepdim=True => (6x1)
  // So broadcast %3 to (6x1)
  %4 = stablehlo.reshape %3 : tensor<6xf32> to tensor<6x1xf32>

  // Subtract mean over dim=1, keepdim=True
  // Compute mean over dim=1 of %4 (shape 6x1)
  // mean = sum / size
  // sum over dim=1 (dim=1 size=1)
  %5 = stablehlo.reduce %4, %cst_0 : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.parameter 0 : tensor<f32>
      %b = stablehlo.parameter 1 : tensor<f32>
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>

  // divide by 1 (size of dim=1)
  %6 = stablehlo.div %5, %cst_1 : tensor<6xf32>

  // reshape mean to (6x1)
  %7 = stablehlo.reshape %6 : tensor<6xf32> to tensor<6x1xf32>

  // subtract mean from %4
  %8 = stablehlo.subtract %4, %7 : tensor<6x1xf32>

  // gelu activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %cst_0_5 = stablehlo.constant 0.5 : f32
  %cst_1 = stablehlo.constant 1.0 : f32
  %cst_sqrt2 = stablehlo.constant 1.4142135381698608 : f32  // approx sqrt(2)

  // x / sqrt(2)
  %9 = stablehlo.div %8, %cst_sqrt2 : tensor<6x1xf32>

  // erf(x / sqrt(2))
  %10 = "chlo.erf"(%9) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // 1 + erf(...)
  %11 = stablehlo.add %cst_1, %10 : tensor<6x1xf32>

  // 0.5 * (1 + erf(...))
  %12 = stablehlo.multiply %cst_0_5, %11 : tensor<6x1xf32>

  // x * 0.5 * (1 + erf(...))
  %13 = stablehlo.multiply %8, %12 : tensor<6x1xf32>

  return %13 : tensor<6x1xf32>
}

// constants
stablehlo.constant dense< -inf > : tensor<f32> {value = -inf} : tensor<f32>
stablehlo.constant 0.0 : tensor<f32>
stablehlo.constant 1.0 : tensor<f32>
stablehlo.constant 0.5 : tensor<f32>
