  } : (tensor<6xf32>) -> tensor<6x1xf32>

  // Subtract mean along dim=1 with keepdim=True from max_broadcast
  // Compute mean of max_broadcast along dim=1 (which is size 1, so mean = value itself)
  // But to follow the spec, compute mean along dim=1 with keepdim
  // mean = sum / size
  %init_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_reduce = stablehlo.reduce %max_broadcast, %init_sum {
