  %sum_broadcast = stablehlo.broadcast_in_dim %sum_reduce {
    broadcast_dimensions = [0]
  } : (tensor<6xf32>) -> tensor<6x1xf32>

  // Create constant 1.0f for division
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {
    broadcast_dimensions = []
  } : (tensor<f32>) -> tensor<f32>

  // Divide sum by 1 (size of dim=1)
  %mean = stablehlo.divide %sum_broadcast, %one_broadcast : tensor<6x1xf32>

  // Subtract mean from max_broadcast
  %sub = stablehlo.subtract %max_broadcast, %mean : tensor<6x1xf32>

  // Apply GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one_f = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>

