    broadcast_dimensions = []
  } : (tensor<f32>) -> tensor<f32>

  // x / sqrt(2)
  %div = stablehlo.divide %sub, %sqrt2_b : tensor<6x1xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %div : tensor<6x1xf32>

  // 1 + erf(...)
  %add_one = stablehlo.add %one_b, %erf : tensor<6x1xf32>

  // x * 0.5
  %mul_half = stablehlo.multiply %sub, %half_b : tensor<6x1xf32>

  // GELU = x * 0.5 * (1 + erf(...))
  %gelu = stablehlo.multiply %mul_half, %add_one : tensor<6x1xf32>

  return %gelu : tensor<6x1xf32>
}
