  // x = self.gemm(x)  # (6,7)
  // x = torch.max(x, dim=1, keepdim=True).values  # (6,1)
  // x = x - x.mean(dim=1, keepdim=True)  # mean over dim=1 of (6,1) is the same as x itself, so zero tensor
