func.func @main(%arg0: tensor<7x6x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x6x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // %arg0: conv.weight: [out_channels=7, in_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: conv.bias: [7]
  // %arg2: input: [batch=6, in_channels=6, height=8, width=8]

  // Perform convolution
  // convolution expects input NHWC or NCHW? StableHLO convolution expects input in NCHW format by default.
  // Our input is [6,6,8,8] (N,C,H,W)
  // weight is [7,6,3,3] (O,I,H,W)
  // We want output shape: [6,7,6,6] (N,O,H_out,W_out)
  // Stride=1, padding=0, dilation=1, feature_group_count=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = {
      // lhs (input) dimension numbers: batch=0, feature=1, spatial=(2,3)
      // rhs (kernel) dimension numbers: output_feature=0, input_feature=1, spatial=(2,3)
      // output dimension numbers: batch=0, feature=1, spatial=(2,3)
      lhs_batch_dimension = 0,
      lhs_feature_dimension = 1,
      lhs_spatial_dimensions = array<i64: 2, 3>,
      rhs_output_feature_dimension = 0,
      rhs_input_feature_dimension = 1,
      rhs_spatial_dimensions = array<i64: 2, 3>,
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = array<i64: 2, 3>
    },
    feature_group_count = 1
  } : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: bias shape [7], output shape [6,7,6,6]
  // Need to broadcast bias to [6,7,6,6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>

  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>

  %conv_bias = "stablehlo.add"(%conv, %bias_broadcast_reshaped) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Define Mish function: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // We will do two Mish applications in sequence.

  // First Mish
  %exp1 = "stablehlo.exponential"(%conv_bias) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %exp1_plus_one = "stablehlo.add"(%exp1, %one_broadcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softplus1 = "stablehlo.log"(%exp1_plus_one) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %tanh1 = "stablehlo.tanh"(%softplus1) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %mish1 = "stablehlo.multiply"(%conv_bias, %tanh1) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Second Mish
  %exp2 = "stablehlo.exponential"(%mish1) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %exp2_plus_one = "stablehlo.add"(%exp2, %one_broadcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softplus2 = "stablehlo.log"(%exp2_plus_one) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %tanh2 = "stablehlo.tanh"(%softplus2) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %mish2 = "stablehlo.multiply"(%mish1, %tanh2) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}
