  %divisor_bcast = stablehlo.broadcast_in_dim %divisor : tensor<f32> to tensor<6x6x3x3x3xf32> {broadcast_dimensions = [0,1,2,3,4]}
  %avg_pooled = stablehlo.divide %avg_sum, %divisor_bcast : tensor<6x6x3x3x3xf32>

