  // lhs = avg_pooled: shape (6,6,3,3,3) [batch, in_channels, D,H,W]
  // rhs = weight_transposed: shape (7,6,3,3,3) [out_channels, in_channels, kD,kH,kW]
  // dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>
  // lhs_dilation = [2,2,2] (stride)
  // rhs_dilation = [1,1,1]
  // padding = [[1,1],[1,1],[1,1]] (padding)
  // output_padding = 1 means output size is increased by 1 in each spatial dim, so we add 1 to the padding high side

  // So padding is [[1,2],[1,2],[1,2]] to account for output_padding=1 on high side
  %padding = stablehlo.constant dense<[[1,2],[1,2],[1,2]]> : tensor<3x2xi64>

