    lhs_dilation = dense<[2,2,2]> : tensor<3xi64>,
    rhs_dilation = dense<[1,1,1]> : tensor<3xi64>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>,
