  // Add bias: %arg2 shape (7), broadcast to (6,7,6,6,6)
  %bias_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7x6x6x6xf32> {broadcast_dimensions = [1]}
