func.func @main(%arg0: tensor<16x3x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x3x1x1xf32> {
  // %arg0: conv.weight: [out_channels=16, in_channels=3, kernel_d=3, kernel_h=3, kernel_w=3]
  // %arg1: conv.bias: [16]
  // %arg2: input: [batch=6, channels=3, depth=16, height=7, width=7]

  // 1) Convolution
  // conv3d with default stride=1, padding=0, dilation=1, feature_group_count=1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = {
      lhs_batch_dimension = 0,
      lhs_feature_dimension = 1,
      lhs_spatial_dimensions = array<i64: 2, 3, 4>,
      rhs_output_feature_dimension = 0,
      rhs_input_feature_dimension = 1,
      rhs_spatial_dimensions = array<i64: 2, 3, 4>,
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = array<i64: 2, 3, 4>
    },
    feature_group_count = 1
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

  // 2) Add bias: broadcast bias from [16] to [6x16x14x5x5]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<16xf32>) -> tensor<6x16x14x5x5xf32>

  %conv_bias = "stablehlo.add"(%conv, %bias_broadcast) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // 3) Softmax along channel dimension (dim=1)
  // Softmax = exp(x) / sum(exp(x), dim=1)
  // Compute exp(x)
  %exp = "stablehlo.exponential"(%conv_bias) : (tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Compute sum over dim=1 (channels)
  %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum = "stablehlo.reduce"(%exp, %init) ( {
    %a = "stablehlo.add"(%arg0, %arg1) : (f32, f32) -> f32
