func.func @main(%arg0: tensor<6x7x3x5xf32>, %arg1: tensor<6x6x7x8xf32>) -> tensor<6x7x9x12xf32> {
  // %arg0: conv_transpose2d.weight with shape [out_channels=6, in_channels=7, kernel_h=3, kernel_w=5]
  // %arg1: input tensor with shape [batch=6, channels=6, height=7, width=8]
  // But from the PyTorch code and signature:
  // conv_transpose2d.weight shape: [in_channels=6, out_channels=7, kernel_h=3, kernel_w=5]
  // input shape: [batch=6, in_channels=6, height=7, width=8]
  // output shape: [batch=6, out_channels=7, height=9, width=12]

  // The weight tensor is given as [6x7x3x5], which matches [in_channels=6, out_channels=7, kernel_h=3, kernel_w=5]
  // input tensor is [6x6x7x8] = [batch=6, in_channels=6, height=7, width=8]
  // output tensor is [6x7x9x12] = [batch=6, out_channels=7, height=9, width=12]

  // ConvTranspose2d parameters:
  // stride=(1,1), padding=(0,0), output_padding=(0,0), dilation=(1,1), groups=1, bias=False

  // Steps:
  // 1. Transpose weight from [in_channels, out_channels, kh, kw] to [out_channels, in_channels, kh, kw]
  // 2. Reverse spatial kernel dims (kh, kw) for conv_transpose2d
  // 3. Use conv with appropriate padding and stride to simulate conv_transpose2d
  //    But since stride=1, padding=0, output_padding=0, dilation=1, groups=1,
  //    the output size is (H_in - 1)*stride - 2*padding + dilation*(kernel_size-1) + output_padding + 1
  //    = (7-1)*1 - 0 + 1*(3-1) + 0 + 1 = 6 + 2 + 1 = 9 height
  //    similarly width = (8-1)*1 - 0 + 1*(5-1) + 0 + 1 = 7 + 4 + 1 = 12 width
  //
  // 4. Implement conv_transpose2d as a conv with reversed kernel and appropriate padding

  // Transpose weight from [in_channels, out_channels, kh, kw] to [out_channels, in_channels, kh, kw]
  %weight_transposed = stablehlo.transpose %arg0 : tensor<6x7x3x5xf32> to tensor<7x6x3x5xf32> {permutation = [1, 0, 2, 3]}

  // Reverse kernel spatial dims (height and width)
  %weight_reversed_h = stablehlo.reverse %weight_transposed : tensor<7x6x3x5xf32> along_dims = [2]
  %weight_reversed_hw = stablehlo.reverse %weight_reversed_h : tensor<7x6x3x5xf32> along_dims = [3]

  // Input tensor shape: [6x6x7x8] = [batch, in_channels, height, width]
  // We need to perform conv with:
  // lhs: input tensor %arg1 [6x6x7x8]
  // rhs: weight_reversed_hw [7x6x3x5]
  // But conv expects rhs shape: [out_channels, in_channels/groups, kernel_h, kernel_w]
  // So weight_reversed_hw is [7x6x3x5] which is correct.

  // Conv dimension numbers for NCHW:
  // input: batch=0, feature=1, spatial=2,3
  // kernel: output_feature=0, input_feature=1, spatial=2,3
  // output: batch=0, feature=1, spatial=2,3

  // Compute output shape: [6,7,9,12]
  // Use stride=1, padding=0, dilation=1, groups=1

  %output = stablehlo.convolution %arg1, %weight_reversed_hw {
    window_strides = [1, 1],
    padding = [0, 0, 0, 0],
    lhs_dilation = [],
    rhs_dilation = [],
    feature_group_count = 1,
    batch_group_count = 1,
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<6x6x7x8xf32>, tensor<7x6x3x5xf32>) -> tensor<6x7x9x12xf32>

  func.return %output : tensor<6x7x9x12xf32>
}
