func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xi64> {
  // We want to compute argmax over dimension 1 (the 7 dimension).
  // Steps:
  // 1) Create an initial max value tensor for reduce: smallest float.
  // 2) Create an initial index tensor for reduce: zeros.
  // 3) Create an iota tensor for dim=1 to track indices.
  // 4) Reduce over dimension 1 with a custom reducer that compares values and selects max and corresponding index.
  //
  // Result shape after argmax over dim=1: [6,8] with i64 indices.

  // Step 1: constant for initial max value: -inf
  %c_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>

  // Step 2: initial index tensor: zeros of shape [6,8], i64
  %c_zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %init_index = stablehlo.broadcast_in_dim %c_zero_i64
    {broadcast_dimensions = array<i64: >} : (tensor<i64>) -> tensor<6x8xi64>

  // Step 3: create iota for dim=1 (the dimension to argmax over)
  // iota shape is [6,7,8], i64, with values 0..6 in dim=0, 0..6 in dim=1, etc.
  // We want iota over dim=1, so values 0..6 repeated along other dims.
  %iota_dim1 = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<6x7x8xi64>

  // Step 4: reduce over dimension 1 (dim=1) with a reducer that keeps max value and index
  // The reduce op takes two inputs: the data tensor and the initial value tensor.
  // We need to reduce the input tensor %arg0 and the iota indices together.
  // But stablehlo.reduce takes one input tensor and one init tensor.
  // So we do reduce on %arg0 with init -inf, and in the reducer we track max value and index.
  // To track index, we need to pass the current index from iota as a parameter to the reducer.
  // StableHLO reduce only passes accumulator and current element, so we need to combine value and index into a tuple.
  // StableHLO does not have tuples, so we do a trick:
  // We do reduce on %arg0 with init -inf, but we also reduce on iota_dim1 with init 0.
  // But stablehlo.reduce only supports one input tensor and one init tensor.
  // So we do a reduce on %arg0 with init -inf, and inside the reducer we get the index from iota_dim1 by extracting the element at the current position.
  // But stablehlo.reduce does not provide the index of the element.
  // So we cannot do that.
  //
  // Alternative approach:
  // We can do a map over dim=1 to compare each element with current max and update max and index.
  // But stablehlo does not have map.
  //
  // Another approach:
  // We can do a reduce_window with window size 1 and stride 1, but that won't help.
  //
  // Another approach:
  // We can do a reduce over dim=1 for max values, then compare input with max values to get a mask, then multiply mask by iota indices and reduce max over dim=1 again to get max index.
  //
  // Let's do that:
  // 1) reduce max over dim=1: get max values tensor [6,8]
  // 2) compare input with max values broadcasted to [6,7,8] to get mask tensor [6,7,8] of i1
  // 3) convert mask to i64 (0 or 1)
  // 4) multiply mask by iota_dim1 (indices)
  // 5) reduce max over dim=1 to get max index [6,8]

  // Step 4.1: reduce max over dim=1
  %init_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>
  %max_values = "stablehlo.reduce"(%arg0, %init_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %cmp = "stablehlo.compare"(%a, %b) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<f32>, tensor<f32>) -> tensor<i1>
      %sel = "stablehlo.select"(%cmp, %a, %b) : (tensor<i1>, tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sel) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x8xf32>

  // Step 4.2: broadcast max_values to shape [6,7,8] to compare with input
  %broadcast_dims = stablehlo.constant dense<[0, 2]> : tensor<2xi64>
  %max_values_broadcast = "stablehlo.broadcast_in_dim"(%max_values)
    {broadcast_dimensions = array<i64: 0, 2>} : (tensor<6x8xf32>) -> tensor<6x7x8xf32>

  // Step 4.3: compare input == max_values_broadcast to get mask
  %mask = "stablehlo.compare"(%arg0, %max_values_broadcast)
    {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x7x8xf32>, tensor<6x7x8xf32>) -> tensor<6x7x8xi1>

  // Step 4.4: convert mask i1 to i64 (0 or 1)
  // stablehlo does not have explicit cast, but we can do select(mask, 1, 0)
  %one_i64 = stablehlo.constant dense<1> : tensor<i64>
  %zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %mask_i64 = "stablehlo.select"(%mask, %one_i64, %zero_i64) : (tensor<6x7x8xi1>, tensor<i64>, tensor<i64>) -> tensor<6x7x8xi64>

  // Step 4.5: multiply mask_i64 by iota_dim1 to get indices where max occurs, zeros elsewhere
  %masked_indices = "stablehlo.multiply"(%mask_i64, %iota_dim1) : (tensor<6x7x8xi64>, tensor<6x7x8xi64>) -> tensor<6x7x8xi64>

  // Step 4.6: reduce max over dim=1 to get max index [6,8]
  %init_zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %max_index = "stablehlo.reduce"(%masked_indices, %init_zero_i64) ({
    ^bb0(%a: tensor<i64>, %b: tensor<i64>):
      %cmp = "stablehlo.compare"(%a, %b) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<i64>, tensor<i64>) -> tensor<i1>
      %sel = "stablehlo.select"(%cmp, %a, %b) : (tensor<i1>, tensor<i64>, tensor<i64>) -> tensor<i64>
      "stablehlo.return"(%sel) : (tensor<i64>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xi64>, tensor<i64>) -> tensor<6x8xi64>

  return %max_index : tensor<6x8xi64>
}
