  // Input to max_pool1d is x.unsqueeze(1) -> shape [6,1,7]
  // So we reshape %2 [6,7] -> [6,1,7]
  %3 = stablehlo.reshape %2 : tensor<6x7xf32> to tensor<6x1x7xf32>

