  // Actually, W is [7,7], so transpose dims 0 and 1
  %0 = stablehlo.transpose %arg1 {permutation = [1, 0]} : tensor<7x7xf32> to tensor<7x7xf32>
  %1 = stablehlo.dot_general %arg5, %0 {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add matmul.bias (broadcast from [7] to [6,7])
  %2 = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>
  // BatchNorm1d forward (training mode)
  // Inputs:
  //   x: %3, shape [6,7]
  //   weight (gamma): %arg3, shape [7]
  //   bias (beta): %arg4, shape [7]
  //   eps: 1e-5 (constant)
  // Compute mean over batch dim (dim 0)
  %c0 = stablehlo.constant 0 : index
  %c1 = stablehlo.constant 1 : index
  %c6f = stablehlo.constant 6.0 : f32
  %c1e_5 = stablehlo.constant 0.00001 : f32
  %mean = stablehlo.reduce %3, %c0, %c1, {
    body(%arg0: tensor<7xf32>, %arg1: tensor<7xf32>) -> tensor<7xf32> {
      %a = stablehlo.add %arg0, %arg1 : tensor<7xf32>
      stablehlo.return %a : tensor<7xf32>
    }
  } : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // mean = sum / 6
  %mean_div = stablehlo.div %mean, %c6f : tensor<7xf32>
  // Compute variance: mean of (x - mean)^2 over batch dim
  // Broadcast mean to [6,7]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %diff = stablehlo.subtract %3, %mean_bcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = stablehlo.reduce %sq, %c0, %c1, {
    body(%arg0: tensor<7xf32>, %arg1: tensor<7xf32>) -> tensor<7xf32> {
      %a = stablehlo.add %arg0, %arg1 : tensor<7xf32>
      stablehlo.return %a : tensor<7xf32>
    }
  } : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = stablehlo.div %var_sum, %c6f : tensor<7xf32>
  // Compute invstd = 1 / sqrt(var + eps)
  %var_eps = stablehlo.add %var, %c1e_5 : tensor<7xf32>
  %sqrt = stablehlo.sqrt %var_eps : tensor<7xf32>
  %invstd = stablehlo.div %c6f, %sqrt : tensor<7xf32>
  // Normalize: (x - mean) * invstd
  %invstd_bcast = stablehlo.broadcast_in_dim %invstd : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %norm = stablehlo.multiply %diff, %invstd_bcast : tensor<6x7xf32>
  // Scale and shift: norm * weight + bias
  %weight_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %bias_bcast = stablehlo.broadcast_in_dim %arg4 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %scaled = stablehlo.multiply %norm, %weight_bcast : tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bias_bcast : tensor<6x7xf32>
  // Add bias parameter %arg0 (shape [1]) broadcast to [6,7]
  %bias_bcast2 = stablehlo.broadcast_in_dim %arg0 : tensor<1xf32> to tensor<6x7xf32> broadcast_dimensions = []
  %add_bias = stablehlo.add %bn_out, %bias_bcast2 : tensor<6x7xf32>
  // Divide by divide_value=1.0 (no-op)
  // Just keep the value as is
  %div = %add_bias
  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %div : tensor<6x7xf32>
  %exp = stablehlo.exp %neg : tensor<6x7xf32>
  %one = stablehlo.constant 1.0 : f32
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_bcast, %exp : tensor<6x7xf32>
  %sigmoid = stablehlo.div %one_bcast, %denom : tensor<6x7xf32>
  %swish = stablehlo.multiply %div, %sigmoid : tensor<6x7xf32>
  stablehlo.return %swish : tensor<6x7xf32>
}
