func.func @main(%bias: tensor<1xf32>, %matmul_weight: tensor<7x7xf32>, %matmul_bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %matmul = input @ matmul_weight^T + matmul_bias
  // matmul_weight shape: [7,7], input shape: [6,7]
  // We want to do input * matmul_weight^T to get [6,7]
  // So transpose matmul_weight: [7,7] -> [7,7] (transpose dims 1,0)
  %matmul_weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul_out = "stablehlo.dot_general"(%input, %matmul_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %matmul_out_bias = stablehlo.add %matmul_out, "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // y = (x - mean) / sqrt(var + eps) * weight + bias
  // mean = reduce mean over batch dim 0 -> shape [7]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%matmul_out_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %six : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // Broadcast mean to [6,7]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %matmul_out_bias, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // Add eps and sqrt
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Add bias (parameter %bias shape [1]) broadcast to [6,7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<1xf32>) -> tensor<6x7xf32>
  %biased = stablehlo.add %bn_out, %bias_broadcast : tensor<6x7xf32>

  // Divide by divide_value=1.0 (no-op, but do it for completeness)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<f32>
  // Actually divide_value is scalar 1.0, so just divide by 1.0 scalar tensor
  %divided = stablehlo.divide %biased, %one : tensor<6x7xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_divided = stablehlo.negate %divided : tensor<6x7xf32>
  %exp_neg = stablehlo.exponential %neg_divided : tensor<6x7xf32>
  %one_scalar = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast_swish = "stablehlo.broadcast_in_dim"(%one_scalar) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<f32>
  %one_plus_exp = stablehlo.add %one_scalar, %exp_neg : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_scalar, %one_plus_exp : tensor<6x7xf32>
  %swish = stablehlo.multiply %divided, %sigmoid : tensor<6x7xf32>

  "stablehlo.return"(%swish) : tensor<6x7xf32>
}
