func.func @main(%arg0: tensor<6x7x5xf32>, %arg1: tensor<6x6x8xf32>) -> tensor<6x7x20xf32> {
  // %arg0: weight tensor of shape [batch=6, out_channels=7, kernel=5]
  // %arg1: input tensor of shape [batch=6, in_channels=6, length=8]

  // Transposed convolution 1D with dilation=3, stride=1, padding=0
  // StableHLO convolution expects input and kernel in specific layouts.
  // PyTorch ConvTranspose1d weight shape: (in_channels, out_channels, kernel_size)
  // Given %arg0 shape: [6,7,5] which matches (batch=6, out_channels=7, kernel=5)
  // But PyTorch ConvTranspose1d weight shape is (in_channels, out_channels, kernel_size)
  // So %arg0 is actually (in_channels=6, out_channels=7, kernel=5) as per problem statement.
  // The problem states %arg0 = conv1d_transpose.weight with shape [6x7x5]
  // So %arg0 shape is [in_channels=6, out_channels=7, kernel=5]

  // The input shape is [6,6,8] = [batch=6, in_channels=6, length=8]

  // For convolution in StableHLO:
  // input: [N, C_in, L_in]
  // kernel: [C_out, C_in, kernel_size]
  // But PyTorch ConvTranspose1d weight is [C_in, C_out, kernel_size]
  // So we need to transpose %arg0 from [6,7,5] (C_in, C_out, K) to [7,6,5] (C_out, C_in, K)

  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = [1, 0, 2]} : (tensor<6x7x5xf32>) -> tensor<7x6x5xf32>

  // Compute output length for transposed conv1d:
  // length_out = (length_in - 1) * stride - 2*padding + dilation*(kernel_size - 1) + output_padding + 1
  // Given stride=1, padding=0, dilation=3, kernel_size=5, output_padding=0
  // length_out = (8 - 1)*1 - 0 + 3*(5-1) + 0 + 1 = 7 + 12 + 1 = 20

  // Set convolution attributes:
  // dimension_numbers: input: NCL, kernel: OIHW (for 1D kernel, W=kernel_size)
  // But StableHLO conv dimension_numbers for 1D conv is:
  // input: [N, C_in, L_in]
  // kernel: [C_out, C_in, K]
  // output: [N, C_out, L_out]

  // Set strides = [1]
  // Set padding = [[0,0]]
  // Set lhs_dilation = [1]
  // Set rhs_dilation = [3] (dilation on kernel)
  // feature_group_count = 1

  %result = "stablehlo.convolution"(%arg1, %weight_transposed) {
    window_strides = [1],
    padding = dense<[[0, 0]]> : tensor<1x2xi64>,
    lhs_dilation = [1],
    rhs_dilation = [3],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2]
    },
    feature_group_count = 1
  } : (tensor<6x6x8xf32>, tensor<7x6x5xf32>) -> tensor<6x7x20xf32>

  return %result : tensor<6x7x20xf32>
}
