func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Perform gemm: x = %arg2 * %arg0^T + %arg1
  // %arg0 is weight of shape [7,7], %arg2 is input [6,7]
  // We want to do a linear layer: output = input * weight^T + bias
  // So we do dot_general with contracting dims: input dim 1 and weight dim 1 (weight transposed)
  %0 = stablehlo.dot_general %arg2, %arg0 {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias from [7] to [6x7]
  %1 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Multiply by multiplier = 2.0 (constant)
  %cst_multiplier = stablehlo.constant 2.0 : f32
  %3 = stablehlo.multiply %2, %cst_multiplier : tensor<6x7xf32>

  // LeakyReLU with negative_slope = 0.1
  // leaky_relu(x) = max(x, 0) + negative_slope * min(x, 0)
  %cst_zero = stablehlo.constant 0.0 : f32
  %4 = stablehlo.maximum %3, %cst_zero : tensor<6x7xf32>
  %5 = stablehlo.minimum %3, %cst_zero : tensor<6x7xf32>
  %cst_neg_slope = stablehlo.constant 0.1 : f32
  %6 = stablehlo.multiply %5, %cst_neg_slope : tensor<6x7xf32>
  %7 = stablehlo.add %4, %6 : tensor<6x7xf32>

  return %7 : tensor<6x7xf32>
}
