  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>  // scalar tensor
  %zero_tensor = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>  // scalar tensor
