  %cmp = "stablehlo.compare"(%mul, %zero_6x7) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xi1>

