```mlir
func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x7x9xf32> {
  // We want to perform 1D average pooling with:
  // kernel_size=8, stride=1, padding=4 on the last dimension of shape 8,
  // input shape: [6,7,8], output shape: [6,7,9].
  // The formula for output length:
  // output_length = floor((input_length + 2*padding - kernel_size)/stride) + 1
  // = floor((8 + 8 - 8)/1) + 1 = floor(8) + 1 = 9

  // Step 1: Pad the input tensor on the last dimension with 4 zeros on each side.
  // StableHLO reduce_window padding attribute is dense<[[pad_before, pad_after], ...]> : tensor<Rx2xi64>
  // For 3D tensor, padding shape is [3,2], we pad only last dim: [0,0], [0,0], [4,4]
  // We will use reduce_window with sum as the reduction function and then divide by kernel_size to get average.

  // Create constant 0.0 for initial value of reduce_window
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>

  // Define window dimensions: kernel size on last dim, 1 on others
  // window_dimensions = [1, 1, 8]
  // window_strides = [1, 1, 1]
  // padding = dense<[[0,0],[0,0],[4,4]]> : tensor<3x2xi64>
  %padding = stablehlo.constant dense<[[0,0],[0,0],[4,4]]> : tensor<3x2xi64>
  %window_dims = stablehlo.constant dense<[1,1,8]> : tensor<3xi64>
  %window_strides = stablehlo.constant dense<[1,1,1]> : tensor<3xi64>

  // Define the reduction function for sum
  %sum_reduce = stablehlo.reduce_window %arg0, %c0 (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  ) {window_dimensions = array<i64: 1, 1, 8>, window_strides = array<i64: 1, 1, 1>, padding = %padding} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x7x9xf32>

  // Create constant for kernel size 8 as f32 scalar tensor for division
  %kernel_size = stablehlo.constant dense<8.0> : tensor<f32>

  // Broadcast kernel_size scalar to shape [6,7,9] for elementwise division
  %kernel_size_broadcast = stablehlo.broadcast_in_dim %kernel_size {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x7x9xf32>

  // Divide sum by kernel size to get average pooling result
  %avg_pool = stablehlo.divide %sum_reduce, %kernel_size_broadcast : tensor<6x7x9xf32>

  return %avg_pool : tensor<6x7x9xf32>
}
