    rhs_contracting_dims = dense<[0]> : tensor<1xi64>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x = "stablehlo.add"(%dot, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

