  %x_sub = "stablehlo.subtract"(%x, %subtract_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1, keepdim
  // sum over dim=1
  %sum = "stablehlo.reduce"(%x_sub) ( {
    %arg_sum = "stablehlo.add"(%arg_0, %arg_1) : (f32, f32) -> f32
    "stablehlo.return"(%arg_sum) : (f32) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // Divide by 7 (size of dim 1)
  %divisor = "stablehlo.constant"() {value = dense<7.0> : tensor<f32>} : () -> tensor<f32>
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x1xf32>
  %mean = "stablehlo.divide"(%sum, %divisor_broadcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  // LogSumExp over dim=1 keepdim
  // Since mean shape is (6x1), logsumexp over dim=1 is just log(exp(x)) = x
  // But to follow the formula, we do logsumexp explicitly:
  // logsumexp(x) = log(sum(exp(x)))
  // exp
  %exp = "stablehlo.exponential"(%mean) : (tensor<6x1xf32>) -> tensor<6x1xf32>
