  %one_b = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x1xf32>
  %sqrt2_b = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x1xf32>

