  // gelu shape (6x1), original_x shape (6x7)
  // broadcast gelu along dim=1 to (6x7)
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6x1xf32>) -> tensor<6x7xf32>

  %residual_add = "stablehlo.add"(%gelu_broadcast, %original_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  "stablehlo.return"(%residual_add) : tensor<6x7xf32>
