  %minus_one_tensor = "stablehlo.broadcast_in_dim"(%minus_one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %one_tensor3 = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>

