  // %arg1: input tensor with shape [batch=8, in_channels=6, height=7, width=8]

  // Step 1: Reverse the kernel spatial dimensions (height and width)
  // Reverse dims 2 and 3 (kernel height and width)
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Perform convolution with reversed kernel and input
  // We want to perform a transposed convolution with:
  // stride = 1, padding = 0, output_padding = 0, groups = 1, bias = False
  // The transposed convolution can be implemented as a convolution with:
  // lhs = input tensor (NCHW): [8,6,7,8]
  // rhs = reversed kernel with swapped in/out channels: [out_channels, in_channels, kh, kw]
  // But our kernel shape is [in_channels, out_channels, kh, kw], so we need to swap in/out channels dims.
  // So we need to transpose kernel from [6,6,3,3] to [6,6,3,3] swapping first two dims.

  // Step 2a: Transpose kernel from [in_channels, out_channels, kh, kw] to [out_channels, in_channels, kh, kw]
  %kernel_transposed = "stablehlo.transpose"(%reversed_kernel) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 3: Convolution dimension numbers for NCHW input and OIHW kernel to NCHW output
  // input dims: [b, f, 0, 1] = [batch, feature, height, width]
  // kernel dims: [o, i, 0, 1] = [out_channels, in_channels, kh, kw]
  // output dims: [b, f, 0, 1] = [batch, feature, height, width]
  // feature_group_count = 1, batch_group_count = 1

  // Step 4: Compute convolution output shape:
  // Using formula:
  // out_height = floor((padding_lo + (in_height - 1)*lhs_dilation + 1 + padding_hi - ((kernel_height - 1)*rhs_dilation + 1)) / stride) + 1
  // Here stride=1, padding=0, lhs_dilation=1, rhs_dilation=1
  // So out_height = in_height + kernel_height - 1 = 7 + 3 - 1 = 9
  // Similarly out_width = 8 + 3 - 1 = 10
  // Output shape: [8, 6, 9, 10]

  %conv = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
