func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x8xf32>) -> tensor<8x6x9x10xf32> {
  // %arg0: conv_transpose2d.weight with shape [out_channels=6, in_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor with shape [batch=8, in_channels=6, height=7, width=8]

  // We want to perform a ConvTranspose2d with:
  // in_channels=6, out_channels=6, kernel_size=3, stride=1, padding=0, output_padding=0, groups=1, bias=False
  // This corresponds to a transposed convolution with stride=1, no padding, no output padding.

  // StableHLO convolution op does not have a direct ConvTranspose op.
  // Transposed convolution can be implemented as a convolution with lhs_dilation and rhs_dilation swapped,
  // or equivalently by using convolution with lhs_dilation = stride and rhs_dilation = 1,
  // and swapping input and kernel roles with appropriate dimension_numbers.

  // The formula for ConvTranspose2d output shape:
  // H_out = (H_in - 1) * stride - 2*padding + kernel_size + output_padding
  // Given stride=1, padding=0, output_padding=0, kernel_size=3:
  // H_out = (7 - 1)*1 - 0 + 3 + 0 = 9
  // W_out = (8 - 1)*1 - 0 + 3 + 0 = 10
  // Matches output shape [8, 6, 9, 10]

  // Dimension numbers for convolution:
  // input: [batch, feature, height, width] = [8, 6, 7, 8]
  // kernel: [out_feature, in_feature, kernel_h, kernel_w] = [6, 6, 3, 3]
  // output: [batch, feature, height, width] = [8, 6, 9, 10]

  // For ConvTranspose2d, the convolution dimension numbers are:
  // lhs = output, rhs = kernel, but we want to use stablehlo.convolution with lhs=input, rhs=kernel.
  // To simulate ConvTranspose2d, we use lhs_dilation = stride (1,1), rhs_dilation = (1,1),
  // and swap input and kernel roles with dimension_numbers adjusted.

  // But stablehlo.convolution does not flip kernel, so to do ConvTranspose2d we:
  // 1) Reverse spatial dims of kernel (flip kernel)
  // 2) Use lhs_dilation = stride (1,1)
  // 3) Use padding = -padding (0)
  // 4) Use dimension_numbers to map input and kernel correctly.

  // Since stride=1, lhs_dilation=1 means no dilation.
  // So we just need to flip kernel spatial dims and do convolution with lhs=input, rhs=flipped kernel.

  // Step 1: reverse kernel spatial dims (dims 2 and 3)
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: convolution with:
  // window_strides = [1, 1]
  // padding = [[0,0],[0,0]]
  // lhs_dilation = [1,1]
  // rhs_dilation = [1,1]
  // dimension_numbers = #conv_dim_nums
  // feature_group_count = 1

  // dimension_numbers for input and kernel:
  // input: batch=0, feature=1, spatial=2,3
  // kernel: out_feature=0, in_feature=1, spatial=2,3
  // output: batch=0, feature=1, spatial=2,3
  // This matches the default conv dimension numbers for stablehlo.convolution

  %conv = "stablehlo.convolution"(%arg1, %reversed_kernel) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x10xf32>

  return %conv : tensor<8x6x9x10xf32>
}

