func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x8xf32>) -> tensor<8x6x9x10xf32> {
  // %arg0: conv_transpose2d.weight with shape [out_channels=6, in_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor with shape [batch=8, in_channels=6, height=7, width=8]

  // To implement ConvTranspose2d using stablehlo.convolution, we use the fact that
  // ConvTranspose2d is a backward convolution with respect to the input.
  // The formula for output shape is:
  // output_size = (input_size - 1) * stride - 2 * padding + kernel_size + output_padding
  // Given stride=1, padding=0, output_padding=0, kernel_size=3,
  // output height = (7 - 1)*1 - 0 + 3 + 0 = 9
  // output width = (8 - 1)*1 - 0 + 3 + 0 = 10
  //
  // The dimension numbers for convolution are:
  // input: [batch, feature, height, width] = [8, 6, 7, 8]
  // kernel: [output_feature, input_feature, kernel_h, kernel_w] = [6, 6, 3, 3]
  // output: [batch, feature, height, width] = [8, 6, 9, 10]
  //
  // For ConvTranspose2d, stablehlo.convolution can be used with:
  // lhs = input tensor
  // rhs = weight tensor
  // lhs_dilation = stride (here 1, so no dilation)
  // rhs_dilation = 1 (no dilation)
  // window_strides = 1 (stride)
  // padding = [[kernel_h - 1 - padding, kernel_h - 1 - padding], [kernel_w - 1 - padding, kernel_w - 1 - padding]]
  // Since padding=0, padding = [[2, 2], [2, 2]]
  //
  // But for ConvTranspose2d, the lhs_dilation attribute is used to upsample the input.
  // Here stride=1, so lhs_dilation = [1,1].
  //
  // The dimension_numbers attribute for convolution is:
  // input: b, f, h, w
  // kernel: o, i, kh, kw
  // output: b, f, h, w
  //
  // feature_group_count = 1
  //
  // So we set:
  // window_strides = [1, 1]
  // padding = [[2, 2], [2, 2]]
  // lhs_dilation = [1, 1]
  // rhs_dilation = [1, 1]
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  //
  // This will produce the transposed convolution output.

  %cst_window_strides = array<i64: 1, 1>
  %cst_padding = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>
  %cst_lhs_dilation = array<i64: 1, 1>
  %cst_rhs_dilation = array<i64: 1, 1>
  %cst_feature_group_count = 1 : i64
  %cst_batch_group_count = 1 : i64

  // dimension_numbers attribute for convolution
  // input: b, f, h, w
  // kernel: o, i, kh, kw
  // output: b, f, h, w
  // This is the default layout for stablehlo convolution.
  // We define it as a symbol attribute.
  %dim_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>

  %conv = "stablehlo.convolution"(%arg1, %arg0) {
    window_strides = %cst_window_strides,
    padding = %cst_padding,
    lhs_dilation = %cst_lhs_dilation,
    rhs_dilation = %cst_rhs_dilation,
    dimension_numbers = %dim_numbers,
    feature_group_count = %cst_feature_group_count,
    batch_group_count = %cst_batch_group_count
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x10xf32>

  return %conv : tensor<8x6x9x10xf32>
}
