  %bias: tensor<16x1x1xf32>, 
  %scale: tensor<16x1x1xf32>, 
  %conv_weight: tensor<16x8x3x3xf32>, 
  %conv_bias: tensor<16xf32>, 
  %gn_weight: tensor<16xf32>, 
  %gn_bias: tensor<16xf32>, 
  %input: tensor<16x8x16x16xf32>
) -> tensor<16x16x14x14xf32> {
  // Convolution:
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>, 
