    feature_group_count = 1 : i64, 
    batch_group_count = 1 : i64
  } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast conv_bias from [16] to [16x16x14x14] on feature dim=1
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x14x14xf32>
  %conv_plus_bias = stablehlo.add %conv, %conv_bias_broadcast : tensor<16x16x14x14xf32>

  // Broadcast bias from [16x1x1] to [16x16x14x14] on dims [1, 2, 3]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %add_bias = stablehlo.add %conv_plus_bias, %bias_broadcast : tensor<16x16x14x14xf32>

  // Broadcast scale from [16x1x1] to [16x16x14x14]
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<16x16x14x14xf32>

  // Sigmoid: 1 / (1 + exp(-x))
  %neg_scaled = stablehlo.negate %scaled : tensor<16x16x14x14xf32>
  %exp_neg_scaled = stablehlo.exponential %neg_scaled : tensor<16x16x14x14xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16x14x14xf32>
  %denominator = stablehlo.add %one_tensor, %exp_neg_scaled : tensor<16x16x14x14xf32>
  %sigmoid = stablehlo.divide %one_tensor, %denominator : tensor<16x16x14x14xf32>

  // GroupNorm:
  // Reshape [16x16x14x14] -> [16x8x2x14x14]
  %reshape1 = stablehlo.reshape %sigmoid : (tensor<16x16x14x14xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute mean over axes [2,3,4]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  // Broadcast mean to [16x8x2x14x14]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute (x - mean)^2
  %diff = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x8x2x14x14xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x8x2x14x14xf32>

  // Compute variance over axes [2,3,4]
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  // Compute inverse stddev = 1 / sqrt(var + epsilon)
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<16x8xf32>
  %sqrt_var_eps = stablehlo.sqrt %var_eps : tensor<16x8xf32>
  %inv_stddev = stablehlo.divide %one, %sqrt_var_eps : tensor<16x8xf32>

  // Normalize: (x - mean) * inv_stddev
  %inv_stddev_broadcast = "stablehlo.broadcast_in_dim"(%inv_stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>
  %normalized = stablehlo.multiply %diff, %inv_stddev_broadcast : tensor<16x8x2x14x14xf32>

  // Reshape normalized back to [16x16x14x14]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x8x2x14x14xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast gn_weight and gn_bias from [16] to [16x16x14x14]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x14x14xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x14x14xf32>

  // Apply scale and bias: normalized * gn_weight + gn_bias
  %scaled_gn = stablehlo.multiply %normalized_reshaped, %gn_weight_broadcast : tensor<16x16x14x14xf32>
  %output = stablehlo.add %scaled_gn, %gn_bias_broadcast : tensor<16x16x14x14xf32>

  return %output : tensor<16x16x14x14xf32>
}
