  // Linear layer: x @ W^T + b
  // %arg0 is weight (7x7), %arg1 is bias (7), %arg2 is input (6x7)
  // We want (6x7) * (7x7)^T = (6x7) * (7x7) but weight is (7x7) so we transpose weight
  %0 = stablehlo.transpose %arg0, permutation = [1, 0] : tensor<7x7xf32> -> tensor<7x7xf32>
