// StableHLO program implementing the described PyTorch model forward pass:
// Inputs:
//   %arg0: linear.weight tensor<7x7xf32> (out_features x in_features)
//   %arg1: linear.bias tensor<7xf32> (out_features)
//   %arg2: input tensor<6x7xf32> (batch_size x in_features)
// Output:
//   tensor<6x1xf32> after linear, logsumexp(dim=1, keepdim=True), leaky_relu twice, gelu twice

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: x = input @ weight^T + bias
  // Note: PyTorch Linear does x @ weight^T + bias
  // %arg0 shape: [7,7] (out_features, in_features)
  // %arg2 shape: [6,7] (batch_size, in_features)
  // We want: [6,7] = [6,7] @ [7,7]^T = [6,7] @ [7,7] (weight transposed)
  // So transpose weight to [7,7] (in_features, out_features) for dot_general
  %weight_t = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<7x7xf32> to tensor<7x7xf32>

  // dot_general with contracting dims: input dim 1 and weight_t dim 0
  %dot = stablehlo.dot_general %arg2, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias from [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1
    : tensor<7xf32> to tensor<6x7xf32>
    broadcast_dimensions = [1]

  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Compute logsumexp over dim=1, keepdim=True
  // Steps:
  // 1) max over dim=1 (for numerical stability)
  %init_max = stablehlo.constant dense<f32 -3.4028235e+38> : tensor<f32> // -inf approx
  %max = stablehlo.reduce %linear_out, %init_max {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [1]} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max to [6,7]
  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %linear_out, %max_broadcast : tensor<6x7xf32>

  // Exponentiate shifted
  %exp = stablehlo.exponential %shifted : tensor<6x7xf32>

  // Sum exp over dim=1
  %init_zero = stablehlo.constant dense<f32 0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce %exp, %init_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [1]} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Log of sum_exp
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>

  // Add max back: logsumexp = max + log(sum(exp(x - max)))
  %logsumexp = stablehlo.add %max, %log_sum_exp : tensor<6xf32>

  // Reshape logsumexp to [6,1] (keepdim=True)
  %logsumexp_reshaped = stablehlo.reshape %logsumexp : tensor<6xf32> to tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<f32 0.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []

  // max(0,x)
  %max_part = stablehlo.maximum %zero_bcast, %logsumexp_reshaped : tensor<6x1xf32>
  // min(0,x)
  %min_part = stablehlo.minimum %zero_bcast, %logsumexp_reshaped : tensor<6x1xf32>

  // negative_slope * min_part
  %neg_slope = stablehlo.constant dense<f32 0.01> : tensor<f32>
  %neg_slope_bcast = stablehlo.broadcast_in_dim %neg_slope : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %neg_scaled = stablehlo.multiply %neg_slope_bcast, %min_part : tensor<6x1xf32>

  // leaky_relu output
  %leaky1 = stablehlo.add %max_part, %neg_scaled : tensor<6x1xf32>

  // Second LeakyReLU (same as above)
  %max_part2 = stablehlo.maximum %zero_bcast, %leaky1 : tensor<6x1xf32>
  %min_part2 = stablehlo.minimum %zero_bcast, %leaky1 : tensor<6x1xf32>
  %neg_scaled2 = stablehlo.multiply %neg_slope_bcast, %min_part2 : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max_part2, %neg_scaled2 : tensor<6x1xf32>

  // GELU twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Constants
  %half = stablehlo.constant dense<f32 0.5> : tensor<f32>
  %one = stablehlo.constant dense<f32 1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<f32 1.4142135> : tensor<f32>

  // Broadcast constants
  %half_bcast = stablehlo.broadcast_in_dim %half : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %sqrt2_bcast = stablehlo.broadcast_in_dim %sqrt2 : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []

  // First GELU
  %x_div_sqrt2 = stablehlo.divide %leaky2, %sqrt2_bcast : tensor<6x1xf32>
  %erf_val = chlo.erf %x_div_sqrt2 : tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_bcast, %erf_val : tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %one_plus_erf : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %half_bcast, %mul1 : tensor<6x1xf32>

  // Second GELU
  %x_div_sqrt2_2 = stablehlo.divide %gelu1, %sqrt2_bcast : tensor<6x1xf32>
  %erf_val_2 = chlo.erf %x_div_sqrt2_2 : tensor<6x1xf32>
  %one_plus_erf_2 = stablehlo.add %one_bcast, %erf_val_2 : tensor<6x1xf32>
  %mul2 = stablehlo.multiply %gelu1, %one_plus_erf_2 : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %half_bcast, %mul2 : tensor<6x1xf32>

  // Return final output
  return %gelu2 : tensor<6x1xf32>
}
