  // %arg0 = linear.weight: [7,7]
  // %arg1 = linear.bias: [7]
  // %arg2 = input: [6,7]

  // Linear layer: x @ W^T + b
  // %arg0 is weight [7,7], we need to transpose it to [7,7] (square, but transpose anyway)
  %weight_t = stablehlo.transpose %arg0 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}
  // DotGeneral: batch matmul input [6,7] x weight_t [7,7] -> [6,7]
  %dot = stablehlo.dot_general %arg2, %weight_t {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // LogSumExp over dim=1 keepdim=True
  // Reduce max for numerical stability
  %init_max = stablehlo.constant dense<f32 -inf> : tensor<f32>
  %max = stablehlo.reduce %linear_out, %init_max {
    dimensions = [1],
    body = {
      %a = stablehlo.parameter 0 : f32
      %b = stablehlo.parameter 1 : f32
      %c = stablehlo.maximum %a, %b : f32
      stablehlo.return %c : f32
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // max shape: [6], broadcast to [6,7]
  %max_bcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %linear_out, %max_bcast : tensor<6x7xf32>

  // exp(shifted)
  %exp = stablehlo.exponential %shifted : tensor<6x7xf32>

  // sum exp over dim=1
  %init_sum = stablehlo.constant dense<f32 0> : tensor<f32>
  %sum_exp = stablehlo.reduce %exp, %init_sum {
    dimensions = [1],
    body = {
      %a = stablehlo.parameter 0 : f32
      %b = stablehlo.parameter 1 : f32
      %c = stablehlo.add %a, %b : f32
      stablehlo.return %c : f32
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>

  // Add max back: logsumexp = max + log(sum_exp)
  %logsumexp = stablehlo.add %max, %log_sum_exp : tensor<6xf32>

  // Reshape logsumexp [6] to [6,1] (keepdim=True)
  %logsumexp_reshaped = stablehlo.reshape %logsumexp : tensor<6xf32> to tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<f32 0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %max0 = stablehlo.maximum %logsumexp_reshaped, %zero_bcast : tensor<6x1xf32>
  %min0 = stablehlo.minimum %logsumexp_reshaped, %zero_bcast : tensor<6x1xf32>
  %neg_slope = stablehlo.constant dense<f32 0.01> : tensor<f32>
  %neg_slope_bcast = stablehlo.broadcast_in_dim %neg_slope : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %mul = stablehlo.multiply %min0, %neg_slope_bcast : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max0, %mul : tensor<6x1xf32>

