  %min1 = stablehlo.minimum %leaky1, %zero_bcast : tensor<6x1xf32>
  %mul2 = stablehlo.multiply %min1, %neg_slope_bcast : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max1, %mul2 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<f32 0.5> : tensor<f32>
  %one = stablehlo.constant dense<f32 1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<f32 1.4142135623730951> : tensor<f32>  // sqrt(2)
  %sqrt2_bcast = stablehlo.broadcast_in_dim %sqrt2 : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %half_bcast = stablehlo.broadcast_in_dim %half : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []

  // First GELU
  %x_div_sqrt2 = stablehlo.divide %leaky2, %sqrt2_bcast : tensor<6x1xf32>
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x1xf32>
  %erf_plus_one = stablehlo.add %erf, %one_bcast : tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %erf_plus_one : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %mul1, %half_bcast : tensor<6x1xf32>

  // Second GELU
  %x_div_sqrt2_2 = stablehlo.divide %gelu1, %sqrt2_bcast : tensor<6x1xf32>
  %erf2 = chlo.erf %x_div_sqrt2_2 : tensor<6x1xf32>
  %erf_plus_one_2 = stablehlo.add %erf2, %one_bcast : tensor<6x1xf32>
  %mul1_2 = stablehlo.multiply %gelu1, %erf_plus_one_2 : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %mul1_2, %half_bcast : tensor<6x1xf32>

  // Return final output
  stablehlo.return %gelu2 : tensor<6x1xf32>
}
