  // %arg0 is weight: [7,7] (out_features x in_features)
  // %arg2 is input: [6,7] (batch_size x in_features)
  // We need to do dot_general with contracting dims: input dim 1 and weight dim 1 (weight transposed)
  %t0 = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias [7] to [6x7]
  %t1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %t2 = stablehlo.add %t0, %t1 : tensor<6x7xf32>

  // LogSumExp over dim=1, keepdim=True
  // Step 1: max over dim=1 for numerical stability
  %c_init = stablehlo.constant dense<-1.000000e+20> : tensor<f32>
  %max = "stablehlo.reduce"(%t2, %c_init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max to [6x7]
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Subtract max for numerical stability
  %t3 = stablehlo.subtract %t2, %max_broadcast : tensor<6x7xf32>
  // Exponentiate
  %t4 = stablehlo.exponential %t3 : tensor<6x7xf32>
  // Sum exp over dim=1
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%t4, %c_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum_val = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Log of sum_exp
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>
  // Add back max
  %log_sum_exp_plus_max = stablehlo.add %log_sum_exp, %max : tensor<6xf32>
  // Reshape to [6x1] by broadcast_in_dim with new dim
  %log_sum_exp_reshaped = "stablehlo.broadcast_in_dim"(%log_sum_exp_plus_max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_6x1 = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  // First LeakyReLU
  %max_part1 = stablehlo.maximum %log_sum_exp_reshaped, %zero_6x1 : tensor<6x1xf32>
  %min_part1 = stablehlo.minimum %log_sum_exp_reshaped, %zero_6x1 : tensor<6x1xf32>
  %slope = stablehlo.constant dense<0.01> : tensor<f32>
  %slope_broadcast = "stablehlo.broadcast_in_dim"(%slope) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %scaled_min1 = stablehlo.multiply %min_part1, %slope_broadcast : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max_part1, %scaled_min1 : tensor<6x1xf32>
  // Second LeakyReLU
  %max_part2 = stablehlo.maximum %leaky1, %zero_6x1 : tensor<6x1xf32>
  %min_part2 = stablehlo.minimum %leaky1, %zero_6x1 : tensor<6x1xf32>
  %scaled_min2 = stablehlo.multiply %min_part2, %slope_broadcast : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max_part2, %scaled_min2 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>  // sqrt(2)
  %inv_sqrt2 = stablehlo.divide %one, %sqrt2 : tensor<f32>
  %inv_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>

  // First GELU
  %x_div_sqrt2_1 = stablehlo.multiply %leaky2, %inv_sqrt2_broadcast : tensor<6x1xf32>
  %erf_1 = "chlo.erf"(%x_div_sqrt2_1) : (tensor<6x1xf32>) -> tensor<6x1xf32>
  %one_plus_erf_1 = stablehlo.add %one_broadcast, %erf_1 : tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %one_plus_erf_1 : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %half_broadcast, %mul1 : tensor<6x1xf32>

  // Second GELU
  %x_div_sqrt2_2 = stablehlo.multiply %gelu1, %inv_sqrt2_broadcast : tensor<6x1xf32>
  %erf_2 = "chlo.erf"(%x_div_sqrt2_2) : (tensor<6x1xf32>) -> tensor<6x1xf32>
  %one_plus_erf_2 = stablehlo.add %one_broadcast, %erf_2 : tensor<6x1xf32>
  %mul2 = stablehlo.multiply %gelu1, %one_plus_erf_2 : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %half_broadcast, %mul2 : tensor<6x1xf32>

  "stablehlo.return"(%gelu2) : tensor<6x1xf32>
}
