  %scale_broadcast = stablehlo.broadcast_in_dim %arg1 
    {broadcast_dimensions = dense<0, 1, 2, 3> : tensor<4xi64>} : tensor<16x1x1xf32> -> tensor<16x16x14x14xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<16x16x14x14xf32>

  // 4) Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_scaled = stablehlo.negate %scaled : tensor<16x16x14x14xf32>
