  %count = stablehlo.constant dense<392.0> : tensor<f32>
  %count_tensor = stablehlo.broadcast_in_dim %count 
    {broadcast_dimensions = dense<> : tensor<0xi64>} : tensor<f32> -> tensor<1xf32>
