  // Broadcast mean to shape of reshape (16x8x2x14x14)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div 
    {broadcast_dimensions = dense<0, 1, 5, 6, 7> : tensor<5xi64>} : tensor<16x8xf32> -> tensor<16x8x2x14x14xf32>

  %diff = stablehlo.subtract %reshape, %mean_broadcast : tensor<16x8x2x14x14xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x8x2x14x14xf32>

