  %init_var_tensor = stablehlo.broadcast_in_dim %init_var 
    {broadcast_dimensions = dense<> : tensor<0xi64>} : tensor<f32> -> tensor<1xf32>
  %var_sum = stablehlo.reduce %diff_sq, %init_var_tensor (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = dense<2, 3, 4> : tensor<3xi64>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  %var = stablehlo.divide %var_sum, %count_broadcast : tensor<16x8xf32>

  // Add eps and sqrt
  %var_eps = stablehlo.add %var, %eps_tensor : tensor<16x8xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<16x

