func.func @main(%arg0: tensor<16x16x3xf32>, %arg1: tensor<16x16x16xf32>) -> tensor<16x16x3xf32> {
  // %arg0: conv1d.weight with shape [out_channels=16, in_channels=16, kernel_size=3]
  // %arg1: input tensor with shape [batch=16, channels=16, length=16]

  // We perform a 1D convolution with:
  // stride = 3
  // dilation = 4
  // no padding (padding = 0)
  // dimension_numbers = [b, f, 0] x [o, i, 0] -> [b, f, 0]
  // where:
  // b = batch dimension
  // f = feature/input channel dimension
  // 0 = spatial dimension (length)
  // o = output channels
  // i = input channels

  %0 = "stablehlo.convolution"(%arg1, %arg0) {
    window_strides = array<i64: 3>,
    padding = dense<[[0, 0]]> : tensor<1x2xi64>,
    lhs_dilation = array<i64: 1>,
    rhs_dilation = array<i64: 4>,
    dimension_numbers = #stablehlo.conv<[b, f, 0]x[o, i, 0]->[b, f, 0]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x16x16xf32>, tensor<16x16x3xf32>) -> tensor<16x16x5xf32>

  // The output shape is [16, 16, 5] because:
  // output_length = floor((0 + (16-1)*1 + 1 + 0 - ((3-1)*4 + 1)) / 3) + 1
  //               = floor((0 + 15 + 1 + 0 - (8 + 1)) / 3) + 1
  //               = floor((16 - 9) / 3) + 1
  //               = floor(7 / 3) + 1 = 2 + 1 = 3
  // But the problem states output tensor shape is tensor<16x16x3xf32>, so we must check carefully.

  // Recalculate output length:
  // Using formula:
  // out = floor((lo + (n-1)*lhs_dilation + 1 + hi - ((k-1)*rhs_dilation + 1)) / stride) + 1
  // lo = 0, hi = 0, n = 16, lhs_dilation = 1, k = 3, rhs_dilation = 4, stride = 3
  // out = floor((0 + 15*1 + 1 + 0 - (2*4 + 1)) / 3) + 1
