  // InstanceNorm2d over input of shape [N=6, C=7, H=8, W=8]
  // Compute mean and variance per instance per channel over spatial dims (H,W)
  // mean = reduce mean over dims [2,3]
  // variance = reduce variance over dims [2,3]
  // output = (input - mean) / sqrt(variance + epsilon)
  // epsilon is a small constant for numerical stability

  %cst_epsilon = stablehlo.constant 1.000000e-05 : tensor<f32>

  // Step 1: Compute mean over dims 2 and 3 (H and W)
  // reduce sum over dims 2 and 3
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_hw = stablehlo.reduce %arg0, %cst_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } {dimensions = dense<2 3> : tensor<2xi64>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute divisor = H*W = 8*8 = 64 as f32 constant
  %cst_64 = stablehlo.constant dense<64.0> : tensor<f32>

  // mean = sum_hw / 64
  %mean = stablehlo.divide %sum_hw, %cst_64 : tensor<6x7xf32>

  // Step 2: Compute variance
  // variance = mean of squared difference from mean
  // Compute (input - mean) with broadcasting mean to shape [6,7,8,8]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean 
    {broadcast_dimensions = dense<0 1> : tensor<2xi64>} : tensor<6x7xf32> -> tensor<6x7x8x8xf32>

  %diff = stablehlo.subtract %arg0, %mean_broadcast : tensor<6x7x8x8xf32>

  // square the diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x8x8xf32>

  // reduce sum of squared diff over dims 2 and 3
  %sum_sq = stablehlo.reduce %diff_sq, %cst_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add2 = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add2 : tensor<f32>
  } {dimensions = dense<2 3> : tensor<2xi64>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // variance = sum_sq / 64
  %variance = stablehlo.divide %sum_sq, %cst_64 : tensor<6x7xf32>

  // Step 3: Compute rsqrt(variance + epsilon)
  %variance_eps = stablehlo.add %variance, %cst_epsilon : tensor<6x7xf32>
  %rsqrt_var = stablehlo.rsqrt %variance_eps : tensor<6x7xf32>

  // Step 4: Broadcast rsqrt_var to input shape [6,7,8,8]
  %rsqrt_var_broadcast = stablehlo.broadcast_in_dim %rsqrt_var 
