  // Given stride=2, padding=1, kernel=3, output_padding=1
  // So padding in StableHLO is:
  // low padding = kernel_size - 1 - padding = 3 - 1 - 1 = 1
  // high padding = low padding + output_padding = 1 + 1 = 2
  // So padding = [[1,2], [1,2]] for height and width dims.

  // Define dimension numbers for convolution:
  // lhs: NCHW = [0,1,2,3]
  // rhs: OIHW = [0,1,2,3]
  // output: NCHW = [0,1,2,3]
