  // output: batch=0, feature=1, spatial dims=2,3
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>

  // Create constant tensors for add_value=0.5 and scale=2.0
  %c_add = stablehlo.constant dense<0.5> : tensor<f32>
  %c_scale = stablehlo.constant dense<2.0> : tensor<f32>

  // Perform convolution (transposed conv)
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 2, 2>,
