  %hardtanh = "stablehlo.minimum"(%maxed, %max_val_broadcast) : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

  // Step 6: Scale output by scale=2 (scalar)
  %scale = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = []} : (tensor<f32>) -> tensor<6x7x12x12xf32>
