func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // %arg3: input tensor with shape [6,7,6,6]
  // %arg1: conv_transpose.weight with shape [7,7,3,3]
  // %arg0: bias parameter with shape [7,1,1]
  // %arg2: conv_transpose.bias with shape [7]
  // scaling_factor = 2.0 constant
  %cst_scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>

  // Perform ConvTranspose2d (transposed convolution)
  // Using convolution operation with dimension_numbers:
  // input: NCHW = [6,7,6,6]
  // kernel: OIHW = [7,7,3,3]
  // output: NCHW = [6,7,12,12]
  // strides = [2,2]
  // padding = [1,1,1,1] (pad_top, pad_bottom, pad_left, pad_right)
  // output_padding = [1,1]
  // dilation = [1,1]
  // feature_group_count = 1

  %conv = stablehlo.convolution %arg3, %arg1 {
    window_strides = [2, 2],
    padding = [1, 1, 1, 1],
    lhs_dilation = [],
    rhs_dilation = [],
    dimension_numbers = #conv_dims,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x11x11xf32>

  // The output shape from above convolution is [6,7,11,11].
  // We need to add output_padding of 1 on height and width to get [6,7,12,12].
  // We can do this by padding the output tensor on the right and bottom by 1.

  %pad_low = stablehlo.constant dense<0> : tensor<i64>
  %pad_high = stablehlo.constant dense<1> : tensor<i64>
  %padding = stablehlo.constant dense<[
    [0, 0],  // batch dim no padding
    [0, 0],  // channel dim no padding
    [0, 1],  // height dim pad 1 on high side
    [0, 1]   // width dim pad 1 on high side
  ]> : tensor<4x2xi64>

  %conv_padded = stablehlo.pad %conv, %pad_low {
    edge_padding_low = [0, 0, 0, 0],
    edge_padding_high = [0, 0, 1, 1],
    interior_padding = [0, 0, 0, 0]
  } : tensor<6x7x11x11xf32> -> tensor<6x7x12x12xf32>

  // Add bias parameter %arg0 (shape [7,1,1]) to conv output (shape [6,7,12,12])
  // Broadcast bias to [6,7,12,12]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7x1x1xf32> to tensor<6x7x12x12xf32> broadcast_dimensions = [1, 0, 2, 3]

  // Actually, the broadcast_dimensions must map bias dims to output dims:
  // bias shape: [7,1,1] dims: 0,1,2
  // output shape: [6,7,12,12] dims: 0,1,2,3
  // We want to broadcast bias dim 0 to output dim 1 (channels),
  // and bias dims 1,2 to output dims 2,3 respectively.
  // So broadcast_dimensions = [1, 2, 3]
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions length = rank of result.
  // So we must reshape bias to 3D and broadcast to 4D with batch dim.

  // Reshape bias from [7,1,1] to [1,7,1,1]
  %bias_reshaped = stablehlo.reshape %arg0 : tensor<7x1x1xf32> to tensor<1x7x1x1xf32>

  // Broadcast bias to [6,7,12,12]
  %bias_broadcasted = stablehlo.broadcast_in_dim %bias_reshaped : tensor<1x7x1x1xf32> to tensor<6x7x12x12xf32> broadcast_dimensions = [0, 1, 2, 3]

  // Add bias to conv output
  %add_bias = stablehlo.add %conv_padded, %bias_broadcasted : tensor<6x7x12x12xf32>

  // Clamp to [0.0, 1.0]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>

  %clamp_min = stablehlo.maximum %add_bias, %zero : tensor<6x7x12x12xf32>
  %clamp_max = stablehlo.minimum %clamp_min, %one : tensor<6x7x12x12xf32>

  // Multiply by scaling_factor (2.0)
  %scaled = stablehlo.multiply %clamp_max, %cst_scaling_factor : tensor<6x7x12x12xf32>

  // Clamp again to [0.0, 1.0]
  %clamp_min2 = stablehlo.maximum %scaled, %zero : tensor<6x7x12x12xf32>
  %clamp_max2 = stablehlo.minimum %clamp_min2, %one : tensor<6x7x12x12xf32>

  // Divide by scaling_factor (2.0)
