  %scale2_bcast = "stablehlo.broadcast_in_dim"(%scale2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x16x7x3x3xf32>
  %output = stablehlo.multiply %biased, %scale2_bcast : tensor<6x16x7x3x3xf32>

  // Return output
  return %output : tensor<6x16x7x3x3xf32>
}
