func.func @main(%scale1: tensor<f32>, %bias: tensor<16x1x1x1xf32>, %scale2: tensor<f32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x16x15x6x6xf32> {
