  // lhs: input tensor dims: [N, C_in, D_in, H_in, W_in] = [6,3,16,7,7]
  // rhs: weight tensor dims: [C_in, C_out, kD, kH, kW] = [3,16,3,3,3]
  // For conv_transpose, the rhs dims are [in_channels, out_channels, kD, kH, kW]
  // The output dims: [N, C_out, D_out, H_out, W_out] = [6,16,15,6,6]
  // The dimension_numbers attribute for conv_transpose is:
  // lhs_spec = [N, C_in, D, H, W] = [0,1,2,3,4]
  // rhs_spec = [C_in, C_out, kD, kH, kW] = [0,1,2,3,4]
