  // Input shape: [16,16] (batch_size, channels)
  // GroupNorm reshapes input to [batch_size, num_groups, channels_per_group]
  // channels_per_group = 16/16 = 1
  // So reshape to [16,16,1]
  %gn_reshape = stablehlo.reshape %fc_out_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gn_reshape, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to [16x16x1]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %gn_reshape, %mean_bcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>
