  %gn_bias_bcast3 = "stablehlo.broadcast_in_dim"(%gn_bias_reshape) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>
  %affine = stablehlo.add %scaled, %gn_bias_bcast3 : tensor<16x16x1xf32>

  // Reshape back to [16x16]
  %gn_out = stablehlo.reshape %affine : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  %zero = stablehlo.constant dense<0.0> : tensor<16x16xf32>
  %cond = "stablehlo.compare"(%gn_out, %zero) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xi1>
