  %neg_slope_bcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %mul = stablehlo.multiply %gn_out, %neg_slope_bcast : tensor<16x16xf32>
  %leaky_relu = "stablehlo.select"(%cond, %gn_out, %mul) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add x + x (element-wise sum)
  %out = stablehlo.add %leaky_relu, %leaky_relu : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}
