  // Input shape: [16,16] (batch_size, channels)
  // GroupNorm divides channels into groups, here each group has 1 channel (16 groups, 16 channels)
  // So group shape: [16, 16] -> reshape to [16, 16, 1] (batch, group, channels_per_group)
  // Actually, channels_per_group = 1, groups=16
  // Compute mean and variance over channels_per_group dimension (dim=2)
  // Then normalize, scale and shift with gn.weight and gn.bias (per channel)
  // Steps:
  // 1) reshape to [16, 16, 1]
  %gn_reshape = stablehlo.reshape %fc_out_biased : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // 2) compute mean over last dim (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gn_reshape, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // mean shape: [16,16]

  // 3) broadcast mean back to [16,16,1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // 4) compute (x - mean)
  %x_centered = stablehlo.subtract %gn_reshape, %mean_broadcast : tensor<16x16x1xf32>

  // 5) compute variance: mean of (x - mean)^2 over dim=2
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
