  %neg_slope = "stablehlo.broadcast_in_dim"(%neg_slope_scalar) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %min_scaled = stablehlo.multiply %min_part, %neg_slope : tensor<16x16xf32>
