func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x1x1x1xf32>, %arg2: tensor<16x3x3x3x3xf32>, %arg3: tensor<16xf32>, %arg4: tensor<6x3x16x7x7xf32>) -> tensor<6x16x14x5x5xf32> {
  // Convolution dimension numbers for 3D conv:
  // input: [batch, channels_in, depth, height, width] = [b, i, d, h, w]
  // kernel: [out_channels, in_channels, kd, kh, kw] = [o, i, kd, kh, kw]
  // output: [batch, channels_out, depth_out, height_out, width_out] = [b, f, d, h, w]
  %0 = "stablehlo.convolution"(%arg4, %arg2) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, f, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

  // Reshape %arg0 (scaling_factor) from tensor<16x1x1x1xf32> to tensor<1x16x1x1x1xf32> for broadcasting
  %1 = stablehlo.reshape %arg0 : tensor<16x1x1x1xf32> -> tensor<16xf32>
  %2 = "stablehlo.broadcast_in_dim"(%1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>

  // Multiply conv output by scaling_factor broadcasted
  %3 = stablehlo.multiply %0, %2 : tensor<6x16x14x5x5xf32>, tensor<1x16x1x1x1xf32>

  // Apply tanh
  %4 = stablehlo.tanh %3 : tensor<6x16x14x5x5xf32>

  // Reshape %arg1 (bias) from tensor<16x1x1x1xf32> to tensor<1x16x1x1x1xf32> for broadcasting
  %5 = stablehlo.reshape %arg1 : tensor<16x1x1x1xf32> -> tensor<16xf32>
  %6 = "stablehlo.broadcast_in_dim"(%5) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>

  // Multiply tanh output by bias broadcasted
  %7 = stablehlo.multiply %4, %6 : tensor<6x16x14x5x5xf32>, tensor<1x16x1x1x1xf32>

  // Apply sigmoid (logistic)
  %8 = stablehlo.logistic %7 : tensor<6x16x14x5x5xf32>

  return %8 : tensor<6x16x14x5x5xf32>
}
