func.func @main(%arg0: tensor<7x6x4x4xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x7x7xf32>) -> tensor<6x6x16x16xf32> {
  // %arg0: conv_transpose.weight: [in_channels=7, out_channels=6, kernel_h=4, kernel_w=4]
  // %arg1: conv_transpose.bias: [6]
  // %arg2: input: [batch=6, in_channels=7, height=7, width=7]

  // StableHLO ConvTranspose2d parameters:
  // Input: %arg2: [N=6, C_in=7, H=7, W=7]
  // Weight: %arg0: [C_in=7, C_out=6, KH=4, KW=4]
  // Output: [N=6, C_out=6, H_out=16, W_out=16] with stride=2, padding=0, dilation=1

  // Step 1: ConvTranspose2d
  // conv_transpose in PyTorch is ConvTranspose2d with stride=2, padding=0, dilation=1, output_padding=0
  // StableHLO conv op with dimension_numbers:
  // input: NCHW
  // kernel: IOHW (input_channels, output_channels, kernel_h, kernel_w)
  // output: NCHW
  // We use conv_transpose by setting window reversal and appropriate strides.

  // Define dimension numbers for conv_transpose:
  // input dims: NCHW = [0,1,2,3]
  // kernel dims: IOHW = [0,1,2,3]
  // output dims: NCHW = [0,1,2,3]

  // ConvTranspose2d can be implemented as a convolution with:
  // - input: %arg2 [N,C_in,H,W]
  // - kernel: %arg0 [C_in,C_out,KH,KW]
  // - window reversal on spatial dims (KH, KW)
  // - strides = [1,1]
  // - rhs_dilation = stride (2,2)
  // - padding = 0

  // So:
  // window reversal on kernel spatial dims (2,3)
  // rhs_dilation = [2,2]
  // padding = 0

  // Create conv with these attributes.

  // Step 1a: Reverse kernel spatial dims (KH, KW)
  %rev_kernel = stablehlo.reverse %arg0 : tensor<7x6x4x4xf32> {dimensions = [2, 3]}

  // Step 1b: Conv with rhs_dilation = stride=2,2
  %conv = stablehlo.convolution %arg2, %rev_kernel {
    window_strides = [1, 1],
    padding = [0, 0, 0, 0],
    lhs_dilate = [],
    rhs_dilate = [2, 2],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_input_feature_dimension = 0,
      kernel_output_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<6x7x7x7xf32>, tensor<7x6x4x4xf32>) -> tensor<6x6x16x16xf32>

  // Step 2: Add bias %arg1 (shape [6]) to conv output (shape [6x6x16x16])
  // Broadcast bias over batch, height, width dims
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<6xf32> to tensor<6x6x16x16xf32> broadcast_dimensions = [1]

  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x16x16xf32>

  // Step 3: Add add_value = 0.5 (constant scalar)
  %cst_add_value = stablehlo.constant 0.5 : f32
  %add_value_broadcast = stablehlo.broadcast_in_dim %cst_add_value : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []

  %add_val = stablehlo.add %add_bias, %add_value_broadcast : tensor<6x6x16x16xf32>

  // Step 4: Minimum with 0.0 (elementwise min with scalar 0.0)
  %cst_zero = stablehlo.constant 0.0 : f32
  %zero_broadcast = stablehlo.broadcast_in_dim %cst_zero : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []

  %min_val = stablehlo.minimum %add_val, %zero_broadcast : tensor<6x6x16x16xf32>

  // Step 5: GELU activation
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Use chlo.erf op

  %cst_half = stablehlo.constant 0.5 : f32
  %cst_one = stablehlo.constant 1.0 : f32
  %cst_sqrt2 = stablehlo.constant 1.4142135381698608 : f32  // approx sqrt(2)

  // x / sqrt(2)
  %div = stablehlo.divide %min_val, %cst_sqrt2 : tensor<6x6x16x16xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %div : tensor<6x6x16x16xf32>

  // 1 + erf(...)
  %one_plus_erf = stablehlo.add %cst_one, %erf : tensor<6x6x16x16xf32>

  // 0.5 * x
