func.func @main(%arg0: tensor<7x6x4x4xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x7x7xf32>) -> tensor<6x6x16x16xf32> {
  // %arg0: conv_transpose.weight with shape [in_channels=7, out_channels=6, kernel_h=4, kernel_w=4]
  // %arg1: conv_transpose.bias with shape [6]
  // %arg2: input tensor with shape [batch=6, in_channels=7, height=7, width=7]

  // We need to perform a ConvTranspose2d with stride=2.
  // StableHLO convolution expects kernel shape [out_channels, in_channels, ...]
  // but PyTorch ConvTranspose weight shape is [in_channels, out_channels, ...].
  // So we must transpose the kernel to [out_channels, in_channels, 4, 4].
  %weight_transposed = stablehlo.transpose %arg0 : tensor<7x6x4x4xf32> to tensor<6x7x4x4xf32> [1, 0, 2, 3]

  // The input shape is [6, 7, 7, 7], which matches batch, in_channels, height, width.
  // The output shape should be [6, 6, 16, 16] (batch, out_channels, H_out, W_out).
  // We set convolution dimension numbers accordingly:
  // input: [b, i, h, w]
  // kernel: [o, i, kh, kw]
  // output: [b, o, ho, wo]
  // This matches dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>
  // For ConvTranspose, we use lhs_dilation = stride, rhs_dilation = 1, window_strides = 1, padding = 0.
  // The formula for ConvTranspose output size:
  // output = (input - 1) * stride - 2*padding + kernel_size
  // Here stride=2, padding=0, kernel=4, input=7
  // output = (7-1)*2 + 4 = 12 + 4 = 16, matches expected output size.

  // Set convolution attributes:
  // window_strides = [1, 1]
  // lhs_dilation = [2, 2] (stride)
  // rhs_dilation = [1, 1]
  // padding = [[0,0],[0,0]]
  // feature_group_count = 1

  %conv = stablehlo.convolution %arg2, %weight_transposed {
    window_strides = [1, 1],
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = [2, 2],
    rhs_dilation = [1, 1],
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x16x16xf32>

  // Add bias: %arg1 shape [6], broadcast to [6,6,16,16] on channel dim=1
  // We broadcast bias to shape [1, 6, 1, 1]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<6xf32> to tensor<1x6x1x1xf32> broadcast_dimensions = [1]

  // Broadcast bias to conv output shape [6x6x16x16]
  %bias_broadcast_full = stablehlo.broadcast_in_dim %bias_broadcast : tensor<1x6x1x1xf32> to tensor<6x6x16x16xf32> broadcast_dimensions = [0, 1, 2, 3]

  %add = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x16x16xf32>

  // Add constant 0.5 (add_value)
  %cst_0_5 = stablehlo.constant 0.5 : f32
  // Broadcast scalar 0.5 to shape [6x6x16x16]
  %cst_0_5_broadcast = stablehlo.broadcast_in_dim %cst_0_5 : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []

  %add_val = stablehlo.add %add, %cst_0_5_broadcast : tensor<6x6x16x16xf32>

  // Take minimum with 0.0 (torch.min(x, 0.0))
  %cst_0_0 = stablehlo.constant 0.0 : f32
  %cst_0_0_broadcast = stablehlo.broadcast_in_dim %cst_0_0 : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []

  %min = stablehlo.minimum %add_val, %cst_0_0_broadcast : tensor<6x6x16x16xf32>

  // Apply GELU: gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt_2 = stablehlo.constant 1.41421356237 : f32
  %sqrt_2_broadcast = stablehlo.broadcast_in_dim %sqrt_2 : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []
  %x_div_sqrt2 = stablehlo.divide %min, %sqrt_2_broadcast : tensor<6x6x16x16xf32>

  // Compute erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x6x16x16xf32>

  // Compute 1 + erf(...)
  %one = stablehlo.constant 1.0 : f32
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x6x16x16xf32>

  // Compute 0.5 * x
  %half = stablehlo.constant 0.5 : f32
  %half_broadcast = stablehlo.broadcast_in_dim %half : tensor<f32> to tensor<6x6x16x16xf32> broadcast_dimensions = []
  %half_x = stablehlo.multiply %half_broadcast, %min : tensor<6x6x16x16xf32>

  // Compute gelu = 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x6x16x16xf32>

  // Multiply by multiply_value = 2.0
