func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
  // %arg0 = gn.weight (scale), shape: [16]
  // %arg1 = gn.bias (shift), shape: [16]
  // %arg2 = input x, shape: [14,16,16,16]

  // GroupNorm parameters:
  // num_groups = 8
  // num_channels = 16
  // So channels per group = 16 / 8 = 2

  // Reshape input to [N, G, C_per_G, H, W] = [14, 8, 2, 16, 16]
  %c14 = stablehlo.constant dense<14> : tensor<i64>
  %c8 = stablehlo.constant dense<8> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c16 = stablehlo.constant dense<16> : tensor<i64>

  %shape_reshaped = stablehlo.constant dense<[14,8,2,16,16]> : tensor<5xi64>
  %x_reshaped = stablehlo.reshape %arg2 : (tensor<14x16x16x16xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute mean over axes [2,3,4] (C_per_G, H, W) per N and G
  // Initial zero for reduce
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %x_reshaped, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[2,3,4]>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute count = 2*16*16 = 512 as f32 constant
  %c512f = stablehlo.constant dense<512.0> : tensor<f32>

  // mean = sum / count
  %mean_div = stablehlo.divide %mean, %c512f : tensor<14x8xf32>

  // Broadcast mean back to shape [14,8,2,16,16]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div
    {broadcast_dimensions = dense<[0,1]>} : tensor<14x8xf32> -> tensor<14x8x2x16x16xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %x_reshaped, %mean_bcast : tensor<14x8x2x16x16xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<14x8x2x16x16xf32>

  %var_sum = stablehlo.reduce %x_centered_sq, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[2,3,4]>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  %var = stablehlo.divide %var_sum, %c512f : tensor<14x8xf32>

  // Add epsilon for numerical stability (eps=1e-5)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<14x8xf32>

  // rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<14x8xf32>

  // Broadcast inv_std to [14,8,2,16,16]
  %inv_std_bcast = stablehlo.broadcast_in_dim %inv_std
    {broadcast_dimensions = dense<[0,1]>} : tensor<14x8xf32> -> tensor<14x8x2x16x16xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast : tensor<14x8x2x16x16xf32>

  // Reshape normalized back to [14,16,16,16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : tensor<14x8x2x16x16xf32> -> tensor<14x16x16x16xf32>

  // Now apply affine transform: scale (weight) and shift (bias)
  // %arg0 = weight (scale), shape [16]
  // %arg1 = bias (shift), shape [16]

  // Broadcast weight and bias to [14,16,16,16]
  %weight_bcast = stablehlo.broadcast_in_dim %arg0
    {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<14x16x16x16xf32>
  %bias_bcast = stablehlo.broadcast_in_dim %arg1
    {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<14x16x16x16xf32>

  // Multiply normalized by weight
  %scaled = stablehlo.multiply %x_norm_reshaped, %weight_bcast : tensor<14x16x16x16xf32>

  // Add bias
  %out = stablehlo.add %scaled, %bias_bcast : tensor<14x16x16x16xf32>

  return %out : tensor<14x16x16x16xf32>
}
