  // Constants for group normalization
  %c8 = stablehlo.constant dense<8> : tensor<i64>          // num_groups
  %c16 = stablehlo.constant dense<16> : tensor<i64>        // num_channels/features
  %c14 = stablehlo.constant dense<14> : tensor<i64>        // batch_size
  %c16_4d = stablehlo.constant dense<16> : tensor<i64>     // spatial dims size
  %c0_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1_f32 = stablehlo.constant dense<1.0> : tensor<f32>
  %c_eps = stablehlo.constant dense<1.0e-5> : tensor<f32>  // epsilon for numerical stability

  // Shapes and ranks
  // input shape: [14,16,16,16]
  // GroupNorm parameters:
  // num_groups = 8
  // num_channels = 16
  // group_size = 16 / 8 = 2 channels per group

  // Compute group_size = num_channels / num_groups = 2
  %c2 = stablehlo.constant dense<2> : tensor<i64>

  // Reshape input from [14,16,16,16] to [14,8,2,16,16]
  %input_reshaped = stablehlo.reshape %input : (tensor<14x16x16x16xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute mean over axes [2,3,4] (group_size and spatial dims)
  // Reduction init value for mean: 0.0
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%input_reshaped, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute divisor = group_size * spatial dims = 2*16*16 = 512
  %c512 = stablehlo.constant dense<512.0> : tensor<f32>

  // Compute mean = sum / 512
  %mean_div = stablehlo.divide %mean, %c512 : tensor<14x8xf32>

  // Broadcast mean to shape [14,8,2,16,16] for subtraction
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<14x8xf32>) -> tensor<14x8x1x1xxf32>
  // Need to broadcast to [14,8,2,16,16], so broadcast dims must be [0,1], and input shape is [14,8]
  // But stablehlo.broadcast_in_dim requires rank(input) == size(broadcast_dimensions)
  // So first reshape mean_div to [14,8,1,1,1]
  %mean_reshaped = stablehlo.reshape %mean_div : (tensor<14x8xf32>) -> tensor<14x8x1x1x1xf32>
  %mean_broadcasted = "stablehlo.broadcast_in_dim"(%mean_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute x_centered = input_reshaped - mean_broadcasted
  %x_centered = stablehlo.subtract %input_reshaped, %mean_broadcasted : tensor<14x8x2x16x16xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<14x8x2x16x16xf32>

  // Reduction init value for variance: 0.0
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute variance = var_sum / 512
  %var = stablehlo.divide %var_sum, %c512 : tensor<14x8xf32>

  // Add epsilon for numerical stability: var + eps
  %var_eps = stablehlo.add %var, %c_eps : tensor<14x8xf32>

  // Compute rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<14x8xf32>

  // Broadcast inv_std to [14,8,2,16,16]
  %inv_std_reshaped = stablehlo.reshape %inv_std : (tensor<14x8xf32>) -> tensor<14x8x1x1x1xf32>
  %inv_std_broadcasted = "stablehlo.broadcast_in_dim"(%inv_std_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Normalize: x_norm = x_centered * inv_std_broadcasted
  %x_norm = stablehlo.multiply %x_centered, %inv_std_broadcasted : tensor<14x8x2x16x16xf32>

  // Reshape x_norm back to [14,16,16,16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : (tensor<14x8x2x16x16xf32>) -> tensor<14x16x16x16xf32>

  // Now apply affine transform: y = x_norm * weight + bias
  // weight and bias shape: [16]
  // Broadcast weight and bias to [14,16,16,16]
  %weight_reshaped = stablehlo.reshape %gn_weight : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %weight_broadcasted = "stablehlo.broadcast_in_dim"(%weight_reshaped) {broadcast_dimensions = array<i64: 1>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>

  %bias_reshaped = stablehlo.reshape %gn_bias : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped) {broadcast_dimensions = array<i64: 1>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>

  // y = x_norm_reshaped * weight_broadcasted + bias_broadcasted
  %scaled = stablehlo.multiply %x_norm_reshaped, %weight_broadcasted : tensor<14x16x16x16xf32>
  %y = stablehlo.add %scaled, %bias_broadcasted : tensor<14x16x16x16xf32>

  return %y : tensor<14x16x16x16xf32>
}
