  // %arg0 = gemm.weight (16x16)
  // %arg1 = gemm.bias (16)
  // %arg2 = group_norm.weight (16)
  // %arg3 = group_norm.bias (16)
  // %arg4 = input (16x16)

  // GEMM: x = input @ weight^T + bias
  // Note: PyTorch Linear does x @ weight^T + bias
  // So we need to transpose weight to do dot_general with contracting dims [1] and [1]
  %weight_t = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<16x16xf32> -> tensor<16x16xf32>
  %gemm = stablehlo.dot_general %arg4, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias (16) to (16x16)
  %bias_bcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> {broadcast_dimensions = [1]}
  %gemm_bias = stablehlo.add %gemm, %bias_bcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, so each channel is its own group
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %reshape1 = stablehlo.reshape %gemm_bias : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over C_per_group dim=2
  %zero = stablehlo.constant 0.0 : tensor<f32>
  %mean = stablehlo.reduce %reshape1, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [2]} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: (16x16), divide by 1 (C_per_group=1), so mean = sum
  // Broadcast mean to (16x16x1)
  %mean_bcast = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> {broadcast_dimensions = [0,1]}

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %reshape1, %mean_bcast : tensor<16x16x1xf32>

  // Compute variance: mean of squared differences
  %sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16x1xf32>
  %var_sum = stablehlo.reduce %sq, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [2]} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = var_sum / 1 = var_sum
  %var_bcast = stablehlo.broadcast_in_dim %var_sum : tensor<16x16xf32> to tensor<16x16x1xf32> {broadcast_dimensions = [0,1]}

  // epsilon for numerical stability
  %epsilon = stablehlo.constant 1.000000e-05 : tensor<f32>
  %epsilon_bcast = stablehlo.broadcast_in_dim %epsilon : tensor<f32> to tensor<16x16x1xf32> {broadcast_dimensions = []}

  // variance + epsilon
  %var_eps = stablehlo.add %var_bcast, %epsilon_bcast : tensor<16x16x1xf32>

  // rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std : tensor<16x16x1xf32>

  // Reshape normalized back to (16x16)
  %x_norm_2d = stablehlo.reshape %x_norm : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: y = weight * x_norm + bias
  // Broadcast group_norm.weight and bias from (16) to (16x16)
  %gn_weight_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> {broadcast_dimensions = [1]}
  %gn_bias_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> {broadcast_dimensions = [1]}

  %scaled = stablehlo.multiply %x_norm_2d, %gn_weight_bcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant -2.0 : tensor<f32>
  %max_val = stablehlo.constant 2.0 : tensor<f32>
  %min_bcast = stablehlo.broadcast_in_dim %min_val : tensor<f32> to tensor<16x16xf32> {broadcast_dimensions = []}
  %max_bcast = stablehlo.broadcast_in_dim %max_val : tensor<f32> to tensor<16x16xf32> {broadcast_dimensions = []}

  %clamp_min = stablehlo.maximum %shifted, %min_bcast : tensor<16x16xf32>
  %clamp = stablehlo.minimum %clamp_min, %max_bcast : tensor<16x16xf32>

  func.return %clamp : tensor<16x16xf32>
}
