  // %arg0 = gemm.weight (16x16), %arg1 = gemm.bias (16), %arg4 = input (16x16)
  // We do dot_general with lhs_batching_dimensions=[0], rhs_batching_dimensions=[0],
  // lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  %dot = "stablehlo.dot_general"(%arg4, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [0],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias (16) to (16x16)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gemm_out = stablehlo.add %dot, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups=16, out_features=16, so group size = 1 (16/16)
  // Reshape gemm_out (N=16, C=16) to (N=16, G=16, group_size=1)
  %reshape1 = stablehlo.reshape %gemm_out : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over group_size dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0,1>} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

