  // dot_general with batch dims = [0], contracting dims = [1] of lhs and [1] of rhs
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %1 = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm parameters:
  // num_groups = 16, so each group has 1 channel (since out_features=16)
  // Reshape x to (N=16, G=16, C_per_group=1)
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over axis=2 (C_per_group=1), so mean is the same as the value itself
  // But we do it generically:
  %c0 = stablehlo.constant dense<0> : tensor<i32>
  %c2 = stablehlo.constant dense<2> : tensor<i32>
  %c3 = stablehlo.constant dense<3> : tensor<i32>

  // Reduce mean over axis=2
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce(%3, %init) ( {
    ^bb0(%a: f32, %b: f32):
      %sum = stablehlo.add %a, %b : f32
      stablehlo.return %sum : f32
  }) {dimensions = [2]} : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // Divide by C_per_group=1 (float 1.0)
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_div = stablehlo.div %mean, %c1f : tensor<16x16xf32>

  // Broadcast mean back to shape (16x16x1)
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  // Compute variance: mean of (x - mean)^2 over axis=2
  %diff = stablehlo.subtract %3, %mean_bcast : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %var_sum = stablehlo.reduce(%sq, %init) ( {
    ^bb0(%a: f32, %b: f32):
