      stablehlo.return %sum : f32
  }) {dimensions = [2]} : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  %var = stablehlo.div %var_sum, %c1f : tensor<16x16xf32>

  // Broadcast var back to (16x16x1)
  %var_bcast = stablehlo.broadcast_in_dim %var : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

