  %norm = stablehlo.multiply %diff, %inv_std : tensor<16x16x1xf32>

  // Reshape norm to (16x16)
  %norm_reshaped = stablehlo.reshape %norm : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: norm * weight + bias
  // weight and bias are (16)
  %weight_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm_reshaped, %weight_bcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_bcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>

  %min_bcast = stablehlo.broadcast_in_dim %min_val : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %max_bcast = stablehlo.broadcast_in_dim %max_val : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %clamp_min = stablehlo.maximum %shifted, %min_bcast : tensor<16x16xf32>
  %clamp = stablehlo.minimum %clamp_min, %max_bcast : tensor<16x16xf32>

  return %clamp : tensor<16x16xf32>
}
