func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0: gemm.weight (16x16)
  // %arg1: gemm.bias (16)
  // %arg2: group_norm.weight (16)
  // %arg3: group_norm.bias (16)
  // %arg4: input (16x16)

  // GEMM: x = input * weight^T + bias
  // dot_general with batch dims = [0], contracting dims = [1]
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {
    lhs_batch_dims = dense<[0]> : tensor<1xi64>,
    rhs_batch_dims = dense<[1]> : tensor<1xi64>,
    lhs_contracting_dims = dense<[1]> : tensor<1xi64>,
    rhs_contracting_dims = dense<[0]> : tensor<1xi64>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias from [16] to [16x16] on dim 1
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1]> : tensor<1xi64>, output_shape = dense<[16,16]> : tensor<2xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %2 = "stablehlo.add"(%0, %1) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // GroupNorm parameters:
  // num_groups = 16, so each group has 1 channel (C=16, G=16, channels_per_group=1)
  // Reshape x from [N=16, C=16] to [N=16, G=16, channels_per_group=1]
  %3 = "stablehlo.reshape"(%2) : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dim (dim=2)
  %4 = "stablehlo.reduce"(%3) ( {
    %acc = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %add = "stablehlo.add"(%acc, %arg0) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = dense<[2]> : tensor<1xi64>} : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Since channels_per_group=1, mean is just the value itself, but we keep the code general:
  // Actually, we can just squeeze dim 2 after reduce, but reduce returns shape [16x16]
  // Compute mean by dividing sum by channels_per_group=1 (no-op)
  %5 = %4 : tensor<16x16xf32>

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to shape [16x16x1]
  %6 = "stablehlo.broadcast_in_dim"(%5) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>, output_shape = dense<[16,16,1]> : tensor<3xi64>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %7 = "stablehlo.subtract"(%3, %6) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %8 = "stablehlo.multiply"(%7, %7) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  %9 = "stablehlo.reduce"(%8) ( {
    %acc = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %add = "stablehlo.add"(%acc, %arg0) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = dense<[2]> : tensor<1xi64>} : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // variance = sum / channels_per_group = no-op since channels_per_group=1
  %10 = %9 : tensor<16x16xf32>

  // Add epsilon for numerical stability: epsilon = 1e-5
  %c_eps = "stablehlo.constant"() {value = dense<1.0e-5> : tensor<f32>} : () -> tensor<f32>
  %11 = "stablehlo.add"(%10, %c_eps) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // rsqrt(variance + eps)
  %12 = "stablehlo.rsqrt"(%11) : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %13 = "stablehlo.subtract"(%3, %6) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %14 = "stablehlo.multiply"(%13, %12) : (tensor<16x16x1xf32>, tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Reshape normalized back to [16x16]
  %15 = "stablehlo.reshape"(%14) : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (scale and shift)
  // Broadcast weight and bias from [16] to [16x16] on dim 1
  %16 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = dense<[1]> : tensor<1xi64>, output_shape = dense<[16,16]> : tensor<2xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %17 = "stablehlo.multiply"(%15, %16) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %18 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[1]> : tensor<1xi64>, output_shape = dense<[16,16]> : tensor<2xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %19 = "stablehlo.add"(%17, %18) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // HardTanh clamp: clamp between -2.0 and 2.0
  %c_min = "stablehlo.constant"() {value = dense<-2.0> : tensor<f32>} : () -> tensor<f32>
  %c_max = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %20 = "stablehlo.maximum"(%19, %c_min) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  %21 = "stablehlo.minimum"(%20, %c_max) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  return %21 : tensor<16x16xf32>
}
