  // - padding = [1, 1, 1] (input padding)
  // - dimension_numbers for ConvTranspose3d:
  //   input: NCDHW (batch, in_channels, depth, height, width)
  //   kernel: OI D H W (out_channels, in_channels/groups, kernel_d, kernel_h, kernel_w)
  //   output: NCDHW (batch, out_channels, depth_out, height_out, width_out)
  //
  // In StableHLO, ConvTranspose3d is done by convolution with:
  // - lhs: input tensor
  // - rhs: kernel tensor
  // - window_strides: stride
  // - padding: padding
  // - feature_group_count: groups
  // - dimension_numbers: lhs_spec = "NCDHW", rhs_spec = "OIDHW", out_spec = "NCDHW"
  //
  // But the weight shape is [in_channels, out_channels, kernel_d, kernel_h, kernel_w]
  // We need to transpose kernel to [out_channels, in_channels/groups, kernel_d, kernel_h, kernel_w]
