  // %arg0: conv_transpose3d.weight with shape [in_channels=6, out_channels=6, kernel_d=3, kernel_h=3, kernel_w=3]
  // %arg1: input tensor with shape [batch=4, in_channels=6, depth=6, height=7, width=8]
  // Parameters from the problem:
  // stride=2, padding=1, groups=4
  // out_channels=6, in_channels=6
  // groups=4 means:
  //   in_channels_per_group = 6 / 4 = 1
  //   out_channels_per_group = 6 / 4 = 1

  // The ConvTranspose3d in PyTorch expects weight shape: (in_channels, out_channels/groups, kD, kH, kW)
  // Here weight shape is (6,6,3,3,3) which matches (in_channels, out_channels, kD, kH, kW)
  // But groups=4 means the convolution is grouped with 4 groups.
  // So the weight tensor is interpreted as 4 groups of:
  //   in_channels_per_group=1
  //   out_channels_per_group=1
  // So the weight shape per group is (1,1,3,3,3)
  // The input channels are split into 4 groups of 1 channel each.
  // The output channels are split into 4 groups of 1 channel each.
  // The output shape is [4,6,11,13,15] as given.

  // StableHLO conv_transpose expects weight shape: [out_channels, in_channels/groups, kD, kH, kW]
  // So we must transpose the weight from [in_channels, out_channels, kD, kH, kW] to [out_channels, in_channels/groups, kD, kH, kW]
  // and reshape accordingly for groups.

  // Step 1: Reshape and transpose weight to [groups, out_channels_per_group, in_channels_per_group, kD, kH, kW]
  %c6 = constant 6 : index
  %c4 = constant 4 : index
  %c1 = constant 1 : index
  %c3 = constant 3 : index
  %c0 = constant 0 : index

  // weight shape: [6,6,3,3,3]
  // reshape to [groups=4, in_channels_per_group=1, out_channels=6, 3,3,3] is not correct
  // Instead, we want to reorder axes to [groups, out_channels_per_group, in_channels_per_group, kD, kH, kW]
  // Original weight dims: [in_channels=6, out_channels=6, kD=3, kH=3, kW=3]
  // We want to split in_channels and out_channels by groups=4:
  // in_channels_per_group=1, out_channels_per_group=1.5? No, out_channels=6, groups=4 => out_channels_per_group=6/4=1.5 invalid.
  // The problem states groups=4, in_channels=6, out_channels=6, so out_channels_per_group=6/4=1.5 which is not integer.
  // But the problem states groups=4, so out_channels must be divisible by groups.
  // The problem's test code says groups=4, out_channels=6, in_channels=6.
  // This is inconsistent with PyTorch's requirement that in_channels and out_channels be divisible by groups.
  // But the problem states groups=4, so we must assume out_channels=6 divisible by 4, which is not.
  // Possibly a mistake in the problem statement, but we must proceed as is.

  // To proceed, we assume groups=4, in_channels=6, out_channels=6, so in_channels_per_group=1.5, out_channels_per_group=1.5
  // This is invalid, but we will treat groups=4 as groups=1 for the convolution in StableHLO to match the output shape.

  // So we ignore groups in the convolution and do a normal conv_transpose3d with stride=2, padding=1.

  // Step 2: Reverse spatial dims of weight to convert conv_transpose to conv
  // PyTorch ConvTranspose3d is implemented as a conv with reversed kernel spatial dims.
  // Reverse kernel dims: kD, kH, kW axes = 2,3,4
  %weight_reversed = stablehlo.reverse %arg0 : tensor<6x6x3x3x3xf32> along #map<2,3,4>

  // Step 3: Transpose weight from [in_channels, out_channels, kD, kH, kW] to [out_channels, in_channels, kD, kH, kW]
  %weight_transposed = stablehlo.transpose %weight_reversed [1,0,2,3,4] : tensor<6x6x3x3x3xf32> to tensor<6x6x3x3x3xf32>

  // Step 4: Prepare convolution parameters
  // Input shape: [4,6,6,7,8]
  // weight shape: [6,6,3,3,3]
  // stride = [2,2,2]
  // padding = [1,1,1]
  // output_padding = 0 (default)
  // dilation = 1 (default)
  // groups = 1 (ignore groups due to inconsistency)

  // Step 5: Compute convolution output shape
  // Output shape is given: [4,6,11,13,15]

  // Step 6: Perform convolution with dimension numbers:
  // input: NCDHW = [batch, in_channels, depth, height, width]
  // kernel: OI D H W = [out_channels, in_channels, kD, kH, kW]
  // output: NCDHW

  // Create constants for strides and padding
  %stride = stablehlo.constant dense<2 2 2> : tensor<3xi64>
  %padding = stablehlo.constant dense<1 1 1> : tensor<3xi64>
  %lhs_dilation = stablehlo.constant dense<1 1 1> : tensor<3xi64>
  %rhs_dilation = stablehlo.constant dense<1 1 1> : tensor<3xi64>

  // Perform convolution
  %conv = stablehlo.convolution %arg1, %weight_transposed {
    window_strides = [2, 2, 2],
    padding = [1, 1, 1, 1, 1, 1], // padding low and high for each spatial dim
    dimension_numbers = #conv_dims,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
    window_dilation = [1, 1, 1],
    lhs_dilation = [1, 1, 1]
  } : (tensor<4x6x6x7x8xf32>, tensor<6x6x3x3x3xf32>) -> tensor<4x6x11x13x15xf32>

  return %conv : tensor<4x6x11x13x15xf32>
}

// Define convolution dimension numbers attribute
// input: NCDHW = [batch, in_channels, depth, height, width]
// kernel: OI D H W = [out_channels, in_channels, kD, kH, kW]
// output: NCDHW
// stablehlo convolution dimension numbers attribute format:
// {input_batch_dimension, input_feature_dimension, input_spatial_dimensions...,
//  kernel_output_feature_dimension, kernel_input_feature_dimension, kernel_spatial_dimensions...,
//  output_batch_dimension, output_feature_dimension, output_spatial_dimensions...}
attr #conv_dims = {
  input_batch_dimension = 0,
  input_feature_dimension = 1,
  input_spatial_dimensions = [2, 3, 4],
  kernel_output_feature_dimension = 0,
  kernel_input_feature_dimension = 1,
  kernel_spatial_dimensions = [2, 3, 4],
  output_batch_dimension = 0,
  output_feature_dimension = 1,
