  %ten_broadcast = "stablehlo.broadcast_in_dim"(%ten) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : (tensor<f32>) -> tensor<16x1xf32>

  %result = "stablehlo.multiply"(%sum_final, %ten_broadcast) : (tensor<16x1xf32>, tensor<16x1xf32>) -> tensor<16x1xf32>

  return %result : tensor<16x1xf32>
}
