  // PyTorch Conv3d default dimension_numbers: NCDHW (batch, channels, depth, height, width)
  // StableHLO conv dimension_numbers: lhs = [b, i, d, h, w], rhs = [o, i, kd, kh, kw], output = [b, o, od, oh, ow]
  // So dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>
  // window_strides = [1,1,1], padding=0, dilation=1, groups=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x7x8x8xf32>, tensor<7x3x3x3x3xf32>) -> tensor<6x7x5x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x5x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<1x7x1x1x1xf32>) -> tensor<6x7x5x6x6xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_reshaped : tensor<6x7x5x6x6xf32>

  // Now apply torch.min along dim=2 (depth dimension after conv)
  // Input shape: [6,7,5,6,6]
  // Reduce min along dimension 2 (depth=5) -> output shape [6,7,6,6]
  // stablehlo.reduce with initial value +inf

  %init_min = stablehlo.constant dense<9.99999975e+37> : tensor<f32>
  %min_reduce = "stablehlo.reduce"(%conv_bias, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min_val = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%min_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x5x6x6xf32>, tensor<f32>) -> tensor<6x7x6x6xf32>

  // Apply softmax along dim=1 (channel dimension)
  // Input shape: [6,7,6,6]
  // Softmax steps:
  // 1) max along dim=1 for numerical stability
  %init_max = stablehlo.constant dense<-9.99999975e+37> : tensor<f32>
  %max_reduce = "stablehlo.reduce"(%min_reduce, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // 2) subtract max from input (broadcast max)
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_reduce) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x1x6x6xf32>) -> tensor<6x7x6x6xf32>
  %shifted = stablehlo.subtract %min_reduce, %max_broadcast : tensor<6x7x6x6xf32>

  // 3) exponentiate
  %exp = stablehlo.exponential %shifted : tensor<6x7x6x6xf32>

  // 4) sum of exp along dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum_val = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // 5) divide exp by sum_exp (broadcast sum_exp)
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x1x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7x6x6xf32>

  // Return softmax output
  return %softmax : tensor<6x7x6x6xf32>
}
