  %count_broadcast = stablehlo.broadcast_in_dim %count {broadcast_dimensions = dense<[0, 1]>} : tensor<f32> -> tensor<6x6xf32>
  %mean_div = stablehlo.divide %mean, %count_broadcast : tensor<6x6xf32>

