  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = dense<[0, 1]>} : tensor<6x6xf32> -> tensor<6x6x4x4xf32>

  // Compute variance:
  // variance = mean((x - mean)^2)
  %diff = stablehlo.subtract %biased, %mean_broadcast : tensor<6x6x4x4xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x6x4x4xf32>

  %init_var = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = dense<>} : tensor<f32> -> tensor<f32>
  %var_sum = stablehlo.reduce %sq_diff, %init_var {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
