  %var_div = stablehlo.divide %var_sum, %count_broadcast : tensor<6x6xf32>

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = dense<[0, 1]>} : tensor<f32> -> tensor<6x6xf32>
  %var_eps = stablehlo.add %var_div, %eps_broadcast : tensor<6x6xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // Broadcast stddev to [6x6x4x4]
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = dense<[0, 1]>} : tensor<6x6xf32> -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x6x4x4xf32>

  // Divide by constant divide_by=2.0
  %divisor = stablehlo.constant dense<2.0> : tensor<f32>
  %divisor_broadcast = stablehlo.broadcast_in_dim %divisor {broadcast_dimensions = dense<>} : tensor<f32> -> tensor<f32>
