  // Compute (x - mean)
  %x_centered = stablehlo.subtract %conv_bias, %mean_bcast2 : tensor<6x6x4x4xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x4x4xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>
  // variance = var_sum / count
  %var = stablehlo.divide %var_sum, %count_bcast : tensor<6x6xf32>

  // Add epsilon for numerical stability (epsilon=1e-5)
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x6xf32>
  %var_eps = stablehlo.add %var, %epsilon_bcast : tensor<6x6xf32>

  // Compute rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6x6xf32>

  // Broadcast inv_std to [6x6x4x4]
  %inv_std_bcast1 = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %inv_std_bcast2 = "stablehlo.broadcast_in_dim"(%inv_std_bcast1) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast2 : tensor<6x6x4x4xf32>

  // 4) Divide by constant 2.0
  %divisor = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scalar divisor to output shape
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %divisor_bcast_full = "stablehlo.broadcast_in_dim"(%divisor_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %output = stablehlo.divide %x_norm, %divisor_bcast_full : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}
