  // Kernel: [out_channels, in_channels, kd, kh, kw] = [16, 3, 3, 3, 3]
  // Output: [batch, out_channels, out_depth, out_height, out_width] = [6, 16, ?, ?, ?]
  // dimension_numbers = #stablehlo.conv<[b, i, 0, 1, 2]x[o, i, 3, 4, 5]->[b, o, 0, 1, 2]>
  // But StableHLO conv dimension_numbers are specified as [input_dims]x[kernel_dims]->[output_dims]
  // For 3D conv: input dims: b, f, d, h, w
  // kernel dims: o, i, kd, kh, kw
  // output dims: b, f, d, h, w
  // So dimension_numbers = #stablehlo.conv<[b, i, d, h, w]x[o, i, kd, kh, kw]->[b, o, d, h, w]>
  // For ConvTranspose3d, we use lhs_dilation = stride, rhs_dilation = 1, and padding as given.
  // lhs_dilation corresponds to dilation of input (upsampling)
  // rhs_dilation corresponds to dilation of kernel (usually 1)
  // window_strides = 1 for ConvTranspose3d
  // padding = padding from PyTorch conv_transpose3d (1)
  // stride = 2

  // Define attributes for convolution:
  %window_strides = dense<1, 1, 1> : tensor<3xi64>
  %lhs_dilation = dense<2, 2, 2> : tensor<3xi64>  // stride=2 means lhs dilation=2
  %rhs_dilation = dense<1, 1, 1> : tensor<3xi64>
  %padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>

  // Perform convolution (transposed conv)
  %conv = stablehlo.convolution %arg2, %weight_transposed {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[b, i, d, h, w]x[o, i, kd, kh, kw]->[b, o, d, h, w]>,
    feature_group_count = 1,
    batch_group_count = 1
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x33x15x15xf32>

  // Add bias: %arg1 shape is [16], broadcast to [6,16,33,15,15]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x33x15x15xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x33x15x15xf32>

  // Multiply by scale = 0.5 (constant)
  %scale = stablehlo.constant 0.5 : f32
  %scale_broadcast = stablehlo.broadcast_in_dim %scale : tensor<f32> to tensor<6x16x33x15x15xf32> broadcast_dimensions = []

  %scaled = stablehlo.multiply %conv_bias, %scale_broadcast : tensor<6x16x33x15x15xf32>

  // MaxPool3d with kernel_size=2, stride=2 (default stride=kernel_size), no padding
  // window_dimensions = [1,1,2,2,2] (batch and channel dims window=1)
  // window_strides = [1,1,2,2,2]
