func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x1x1x1xf32> {
  // conv_transpose.weight: %arg0 shape [in_channels=3, out_channels=16, kD=3, kH=3, kW=3]
  // conv_transpose.bias: %arg1 shape [16]
  // input: %arg2 shape [batch=6, in_channels=3, D=16, H=7, W=7]

  // Parameters for conv_transpose:
  // stride=2, padding=1
  // PyTorch ConvTranspose3d input: (N, C_in, D_in, H_in, W_in)
  // weight shape: (C_in, C_out, kD, kH, kW)
  // output shape: (N, C_out, D_out, H_out, W_out)
  // D_out = (D_in - 1) * stride - 2*padding + kernel_size
  //       = (16-1)*2 - 2*1 + 3 = 30 + 1 = 31
  // H_out = (7-1)*2 - 2*1 + 3 = 12 + 1 = 13
  // W_out = same as H_out = 13

  // StableHLO conv dimension numbers for ConvTranspose:
  // input: NCDHW = [0,1,2,3,4]
  // kernel: OIxyz = [1,0,2,3,4] (PyTorch weight is (C_in, C_out, kD,kH,kW), but StableHLO expects (O,I,D,H,W))
  // So we must transpose weight from (C_in, C_out, kD, kH, kW) to (C_out, C_in, kD, kH, kW)
  // We do this by a transpose op.

  // ConvTranspose in StableHLO is a convolution with window reversal and dilation on input.
  // We use conv with dimension_numbers and window reversal to simulate ConvTranspose3d.

  // Step 1: transpose weight from (3,16,3,3,3) to (16,3,3,3,3)
  %weight_transposed = stablehlo.transpose %arg0 : tensor<3x16x3x3x3xf32> to tensor<16x3x3x3x3xf32> {permutation = [1,0,2,3,4]}

  // Step 2: conv_transpose via conv with input dilation and padding
  // input dilation = stride - 1 = 1 (since stride=2)
  // padding = kernel_size - 1 - padding = 3 - 1 - 1 = 1 (for each spatial dim)
  // So padding = 1 on all spatial dims

  // Define dimension numbers for conv:
  // input: NCDHW = [0,1,2,3,4]
  // kernel: OIDHW = [0,1,2,3,4]
  // output: NCDHW = [0,1,2,3,4]

  // Create conv window with dilation on input (input dilation = stride -1 = 1)
  // padding = 1 on all spatial dims

  // Create conv op
  %conv = stablehlo.convolution %arg2, %weight_transposed {
    window_strides = [1,1,1],
    padding = [[1,1],[1,1],[1,1]],
    lhs_dilation = [2,2,2],  // input dilation = stride=2 means lhs_dilation = stride
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2,3,4],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2,3,4],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2,3,4]
    },
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {}
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Step 3: add bias (broadcast bias from [16] to [6,16,31,13,13])
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x31x13x13xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x31x13x13xf32>

  // Step 4: multiply by scale=0.5 (constant)
  %scale = stablehlo.constant 0.5 : f32
  %scale_broadcast = stablehlo.broadcast_in_dim %scale : tensor<f32> to tensor<6x16x31x13x13xf32> broadcast_dimensions = []
  %scaled = stablehlo.multiply %conv_bias, %scale_broadcast : tensor<6x16x31x13x13xf32>

  // Step 5: maxpool3d with kernel_size=2, stride=2 (default stride=kernel_size), no padding
  // maxpool kernel: [2,2,2]
  // input shape: [6,16,31,13,13]
  // output shape: floor((input - kernel)/stride + 1)
  // D_out = floor((31-2)/2 +1) = floor(29/2 +1) = floor(14.5+1)=15
  // H_out = floor((13-2)/2 +1) = floor(11/2 +1)=floor(5.5+1)=6
  // W_out = same as H_out=6

  %maxpool = stablehlo.reduce_window %scaled {
    window_dimensions = [1,1,2,2,2],
    window_strides = [1,1,2,2,2],
