func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0: linear.weight (7x7)
  // %arg1: linear.bias (7)
  // %arg2: input (6x7)

  // Linear layer: x @ W^T + b
  // W^T shape: 7x7 -> transpose to 7x7 (same shape, but we transpose)
  %0 = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<7x7xf32> to tensor<7x7xf32>
  // Dot product: batch matmul (6x7) x (7x7) -> (6x7)
  %1 = stablehlo.dot_general %arg2, %0 {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %2 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>

  // sum over dim=1 keepdim=True: reduce sum over dim 1
  %4 = stablehlo.reduce %3, %cst0 : tensor<6x7xf32>, tensor<f32> {
    dimensions = [1],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // max over dim=1 keepdim=True: reduce max over dim 1
  %5 = stablehlo.reduce %4, %cst_minf : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body {
      %a = stablehlo.maximum %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True: reduce sum over dim 1 then divide by size=1
  // But dim=1 size=1, so mean is the same as the value itself.
  // So mean is identity here, but we implement it anyway for correctness.

  // sum over dim=1 keepdim=True (dim size=1)
  %6 = stablehlo.reduce %5, %cst0 : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // divide by 1 (dim size)
  %7 = stablehlo.div %6, %cst1 : tensor<6x1xf32>, tensor<f32>

  // logsumexp over dim=1 keepdim=True
  // logsumexp(x) = log(sum(exp(x)))
  // dim=1 size=1, so sum over single element = element itself
  // So logsumexp is log(exp(x)) = x
  // But implement fully for correctness.

  // exp
  %8 = stablehlo.exp %7 : tensor<6x1xf32>

  // sum over dim=1 keepdim=True
  %9 = stablehlo.reduce %8, %cst0 : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // log
  %10 = stablehlo.log %9 : tensor<6x1xf32>

  // logsumexp again (same as above)
  %11 = stablehlo.exp %10 : tensor<6x1xf32>
  %12 = stablehlo.reduce %11, %cst0 : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
