func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x * W^T + b
  // %arg0: weight (7x7), %arg1: bias (7), %arg2: input (6x7)
  // We want: (6x7) dot (7x7)^T = (6x7) dot (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape), but we want to contract input dim 1 with weight dim 1
  // We'll do dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  // But weight is (7x7), input is (6x7), so to do x * W^T, we transpose weight first

  // Transpose weight to get W^T: (7x7) -> (7x7) (swap dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot product: (6x7) dot (7x7) -> (6x7)
  %dot = "stablehlo.dot_general"(%arg2, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // sum over dim=1 keepdim=True: reduce sum over dim 1 -> shape (6x1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%linear_out, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Add back dim 1 for keepdim=True: broadcast sum (6) to (6x1)
  %sum_keepdim = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // max over dim=1 keepdim=True: max of (6x1) over dim 1 is trivial (dim=1 size=1), so max is identity
  // But to follow spec, do max reduce over dim=1
  // Since dim=1 is size 1, max is the same value, but we do it anyway
  %neg_inf = stablehlo.constant dense<-inf> : tensor<f32>
  %max = "stablehlo.reduce"(%sum_keepdim, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  %max_keepdim = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True: mean of (6x1) over dim 1 is same as value (dim=1 size=1)
  // But do it explicitly: sum / size
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %size = stablehlo.constant dense<1.0> : tensor<f32>  // size of dim=1 is 1
  %mean = %max_keepdim  // mean is same as max_keepdim since size=1

  // logsumexp over dim=1 keepdim=True: input shape (6x1)
  // logsumexp(x) = log(sum(exp(x)))
  // Compute exp
  %exp = stablehlo.exponential %mean : tensor<6x1xf32>
  // sum over dim=1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  %sum_exp_keepdim = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // log
  %logsumexp = stablehlo.log %sum_exp_keepdim : tensor<6x1xf32>

