  %exp2 = stablehlo.exponential %logsumexp : tensor<6x1xf32>
  %sum_exp2 = "stablehlo.reduce"(%exp2, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
