  // input: x_mish [16x16], num_groups=16, so each group has 1 channel (channel dim = 1)
  // GroupNorm per group: normalize over group channels dimension (dim=1)
  // mean = reduce_mean over dim=1 (channels)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean_sum = "stablehlo.reduce"(%x_mish, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
