func.func @main(%arg0: tensor<6x6x3x7xf32>, %arg1: tensor<8x6x7x8xf32>) -> tensor<8x6x7x8xf32> {
  // %arg0: weight tensor of shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=7]
  // %arg1: input tensor of shape [batch=8, in_channels=6, height=7, width=8]

  // ConvTranspose2d parameters:
  // stride = (1,1)
  // padding = (1,3)
  // dilation = (1,1)
  // groups = 1

  // StableHLO convolution expects weight shape: [out_channels, in_channels/groups, kernel_h, kernel_w]
  // Our weight is [in_channels, out_channels, kernel_h, kernel_w], so we need to transpose the first two dims.

  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = dense<[1, 0, 2, 3]> : tensor<4xi64>} : (tensor<6x6x3x7xf32>) -> tensor<6x6x3x7xf32>

  // Compute output spatial dimensions for conv_transpose2d:
  // output_height = (input_height - 1) * stride_h - 2*padding_h + dilation_h*(kernel_h - 1) + 1
  // output_width  = (input_width - 1) * stride_w - 2*padding_w + dilation_w*(kernel_w - 1) + 1
  // Given stride=1, padding=(1,3), dilation=1, kernel=(3,7), input=(7,8):
  // output_height = (7-1)*1 - 2*1 + 1*(3-1) + 1 = 6 - 2 + 2 + 1 = 7
  // output_width  = (8-1)*1 - 2*3 + 1*(7-1) + 1 = 7 - 6 + 6 + 1 = 8
  // So output spatial dims = (7,8), same as input spatial dims.

  // The conv_transpose2d in PyTorch is implemented as a backward convolution with respect to input.
  // In StableHLO, we can use convolution with feature_group_count=1, and set the window strides and padding accordingly.
  // For conv_transpose2d, the equivalent forward convolution is:
  // output = conv(input, weight, window_strides=1, padding=padding, lhs_dilation=stride, rhs_dilation=dilation)
  // But since stride=1 and dilation=1, lhs_dilation and rhs_dilation are 1.
  // The padding for conv_transpose2d corresponds to output_padding in conv, but here output_padding=0.
  // So we can use convolution with padding = (kernel_size - 1 - padding)
  // But since PyTorch conv_transpose2d padding is the amount of zero padding added to input, in StableHLO we must adjust padding accordingly.

  // For conv_transpose2d, the equivalent convolution padding is:
  // padding_conv = kernel_size - 1 - padding_transpose
  // Given padding=(1,3), kernel=(3,7):
  // padding_conv_h = 3 - 1 - 1 = 1
  // padding_conv_w = 7 - 1 - 3 = 3

  // So the convolution padding is [[1,1],[3,3]] (symmetric padding on both sides)

  // We set window_strides = [1,1]
  // feature_group_count = 1
  // lhs_dilation = [1,1]
  // rhs_dilation = [1,1]

  // Prepare padding attribute as dense tensor of shape [2,2] with [[1,1],[3,3]]
  %padding = "stablehlo.constant"() {value = dense<[[1, 1], [3, 3]]> : tensor<2x2xi64>} : () -> tensor<2x2xi64>

  %result = "stablehlo.convolution"(%arg1, %weight_transposed) {
    window_strides = dense<[1, 1]> : tensor<2xi64>,
    padding = %padding,
    lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    feature_group_count = 1,
    batch_group_count = 1,
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x7xf32>) -> tensor<8x6x7x8xf32>

  return %result : tensor<8x6x7x8xf32>
}
