func.func @main(%bias: tensor<7x1x1xf32>, %conv_transpose_weight: tensor<7x7x4x4xf32>, %conv_transpose_bias: tensor<7xf32>, %input: tensor<6x7x8x8xf32>) -> tensor<6x7x17x17xf32> {
  // Perform ConvTranspose2d with stride=2, padding=1, output_padding=1
  // Using stablehlo.convolution with rhs_dilation = stride, padding adjusted for output_padding
  // dimension_numbers for ConvTranspose2d: lhs = [b, i, h, w], rhs = [i, o, kh, kw], output = [b, o, ho, wo]
  // Here input shape: [6,7,8,8], weight shape: [7,7,4,4]
  // We want output shape: [6,7,17,17]
  // So dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>
  // rhs_dilation = stride = [2,2]
  // padding = [[1,1],[1,1]] (padding on input)
  // output_padding=1 is handled by padding and output shape

  %conv = "stablehlo.convolution"(%input, %conv_transpose_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 2, 2>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x8x8xf32>, tensor<7x7x4x4xf32>) -> tensor<6x7x17x17xf32>

  // Broadcast bias from [7,1,1] to [6,7,17,17]
  // First broadcast bias to [7,17,17]
  %bias_broadcast_1 = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<7x1x1xf32>) -> tensor<7x17x17xf32>
  // Then broadcast to batch dimension 6: [6,7,17,17]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias_broadcast_1) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x17x17xf32>) -> tensor<6x7x17x17xf32>

  // Subtract bias from conv output
  %sub = stablehlo.subtract %conv, %bias_broadcast : tensor<6x7x17x17xf32>

  // Apply tanh activation
  %tanh = stablehlo.tanh %sub : tensor<6x7x17x17xf32>

  return %tanh : tensor<6x7x17x17xf32>
}
