  // weight: [C_in, C_out, KH, KW] = %arg1 but PyTorch conv_transpose weight shape is [C_in, C_out, KH, KW]
  // However, PyTorch conv_transpose weight shape is [in_channels, out_channels, KH, KW]
  // StableHLO convolution expects kernel shape [O, I, KH, KW]
  // So we need to transpose %arg1 from [7,7,4,4] (in_channels, out_channels, KH, KW) to [7,7,4,4] (out_channels, in_channels, KH, KW)
  // But here in_channels=7, out_channels=7, so shape is symmetric, but we must swap dims 0 and 1.

  // Transpose kernel from [in_channels, out_channels, KH, KW] to [out_channels, in_channels, KH, KW]
  %kernel_transposed = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x7x4x4xf32>) -> tensor<7x7x4x4xf32>

