  // For ConvTranspose2d, the equivalent convolution parameters are:
  // lhs = input, rhs = kernel
  // window_strides = 1 (because stride is handled by lhs_dilation)
  // lhs_dilation = stride = 2
  // rhs_dilation = 1
  // padding = padding - output_padding = 1 - 1 = 0 (but we must compute padding carefully)
  // Actually, for ConvTranspose2d, output shape is computed as:
  // output = (input - 1) * stride - 2*padding + kernel + output_padding
  // So padding in convolution is 0, lhs_dilation = stride=2, rhs_dilation=1
  // We set padding = 1 (from PyTorch padding param)
  // But in StableHLO, for transposed convolution, lhs_dilation corresponds to stride in ConvTranspose2d
  // So we set lhs_dilation = [2, 2]
  // padding = [1, 1] (from PyTorch padding)
  // output_padding is handled by adjusting padding or output shape, but StableHLO convolution does not have output_padding param
  // We can handle output_padding by padding the input or output, but here we will set padding to 1 and rely on lhs_dilation and output shape.

  // Define dimension numbers for convolution:
  // input: [N, C_in, H, W] = [6,7,8,8]
  // kernel: [O, I, KH, KW] = [7,7,4,4]
  // output: [N, C_out, H_out, W_out] = [6,7,17,17]
  // dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>
  // where b=batch, i=input channels, o=output channels, 2=height dim, 3=width dim

  %conv = "stablehlo.convolution"(%arg3, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x8x8xf32>, tensor<7x7x4x4xf32>) -> tensor<6x7x17x17xf32>

  // Now subtract bias from conv output
  // bias shape: [7,1,1], conv output shape: [6,7,17,17]
  // Broadcast bias to [6,7,17,17]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x17x17xf32>

  // Actually, %arg0 shape is [7,1,1], we need to broadcast to [6,7,17,17]
  // But stablehlo.broadcast_in_dim requires input rank = output rank
  // So first we reshape %arg0 to [1,7,1,1] to match output rank 4
  %bias_reshaped = "stablehlo.reshape"(%arg0) : (tensor<7x1x1xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x17x17xf32>

  // Subtract bias from conv output
  %sub = "stablehlo.subtract"(%conv, %bias_broadcast) : (tensor<6x7x17x17xf32>, tensor<6x7x17x17xf32>) -> tensor<6x7x17x17xf32>

  // Apply tanh activation
  %tanh = "stablehlo.tanh"(%sub) : (tensor<6x7x17x17xf32>) -> tensor<6x7x17x17xf32>

