  // filter: %weight_transposed [4,4,7,7]
  // strides: [2,2]
  // padding: [1,1]
  // output_padding: [1,1]
  // feature_group_count: 1
  // dimension_numbers: input NHWC or NCHW? Input is NCHW: [batch, in_channels, height, width]
  // StableHLO convolution dimension_numbers attribute is a struct with input, kernel, output dimension mappings.
  // For NCHW input and kernel with spatial dims first, dimension_numbers is:
  // input: [0,1,2,3] = N,C,H,W
  // kernel: [2,3,1,0] = H,W,in_channels,out_channels
  // output: [0,1,2,3] = N,C,H,W

  // We want to do a transposed convolution, so set transpose = true.

  %conv = "stablehlo.convolution"(%arg3, %weight_transposed) {
