func.func @main(%weight: tensor<6x7x3x3xf32>, %bias: tensor<7xf32>, %input: tensor<16x6x7x7xf32>) -> tensor<16x7x1x1xf32> {
  // Transpose conv parameters to match stablehlo.convolution lhs and rhs:
  // PyTorch ConvTranspose2d weight shape: (in_channels=6, out_channels=7, kH=3, kW=3)
  // stablehlo.convolution expects rhs shape: (out_channels, in_channels, kH, kW)
  // So we need to transpose weight from (6,7,3,3) to (7,6,3,3)
  %weight_t0 = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x7x3x3xf32>) -> tensor<7x6x3x3xf32>

  // stablehlo.convolution dimension_numbers for ConvTranspose2d:
  // Input (lhs) shape: (N, C_in, H_in, W_in) = (16,6,7,7)
  // Weight (rhs) shape: (C_in, C_out, kH, kW) in PyTorch, but stablehlo expects (C_out, C_in, kH, kW)
  // Output shape: (N, C_out, H_out, W_out) = (16,7,15,15) with stride=2, padding=1, output_padding=1, kernel=3
  // For ConvTranspose2d, stablehlo.convolution is used with lhs_dilation=stride, rhs_dilation=1, and padding adjusted.
  // We set:
  // window_strides = [1,1]
  // lhs_dilation = [2,2] (stride)
  // rhs_dilation = [1,1]
  // padding = [[1,1],[1,1]] (padding)
  // output_padding is handled by adjusting padding or output shape, but stablehlo.convolution does not have output_padding attribute.
  // To handle output_padding=1, we add 1 to the output spatial dims by padding the input or adjusting padding.
  // The formula for output shape in ConvTranspose2d:
  // H_out = (H_in - 1) * stride - 2*padding + kernel + output_padding
  // Here: (7-1)*2 - 2*1 + 3 + 1 = 12 - 2 + 3 + 1 = 14
  // But the example output shape is 15x15, so output_padding=1 adds 1 more.
  // stablehlo.convolution does not have output_padding attribute, so we simulate by padding input or output.
  // We will pad input spatial dims by 1 on the right to simulate output_padding=1.
  // So pad input: padding = [[0,0],[0,0],[0,1],[0,1]]

  // Pad input tensor spatial dims (H,W) with 0 low, 1 high padding
  %pad_value = stablehlo.constant dense<0.0> : tensor<f32>
  %padded_input = "stablehlo.pad"(%input, %pad_value) {padding = dense<[[0,0],[0,0],[0,1],[0,1]]> : tensor<4x2xi64>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16x6x8x8xf32>

  // Now perform convolution with lhs_dilation=stride=2, rhs_dilation=1, padding=1 on each side
  %conv = "stablehlo.convolution"(%padded_input, %weight_t0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
