  // Transpose kernel from [6,7,3,3] to [7,6,3,3]
  %weight_transposed = stablehlo.transpose %arg0 : tensor<6x7x3x3xf32> to tensor<7x6x3x3xf32> {permutation = [1, 0, 2, 3]}

  // ConvTranspose2d is a backward convolution with respect to the forward convolution.
  // We can implement ConvTranspose2d as a convolution with lhs_dilation = stride,
  // rhs_dilation = 1, and appropriate padding.
  // The formula for output shape of ConvTranspose2d:
  // output = (input - 1) * stride - 2*padding + kernel_size + output_padding
  // Given stride=2, padding=1, kernel=3, output_padding=1
  // output spatial dims = (7-1)*2 - 2*1 + 3 + 1 = 12 - 2 + 3 + 1 = 14

  // StableHLO convolution dimension_numbers for 4D conv:
  // input: [batch, feature, height, width]
  // kernel: [out_feature, in_feature, kernel_h, kernel_w]
  // output: [batch, feature, height, width]
  // dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>

  // For ConvTranspose2d, lhs_dilation = stride = [2, 2]
  // rhs_dilation = [1, 1]
  // window_strides = [1, 1]
  // padding = [[padding_top, padding_bottom], [padding_left, padding_right]] = [[1,1],[1,1]]

  // We set feature_group_count=1, batch_group_count=1

  // Perform convolution with lhs_dilation=stride to simulate ConvTranspose2d
  %conv = stablehlo.convolution %arg2, %weight_transposed {
    window_strides = [1, 1],
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = [2, 2],
    rhs_dilation = [1, 1],
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x6x7x7xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x14x14xf32>

