  %multiplier_broadcast = stablehlo.broadcast_in_dim %multiplier : tensor<f32> to tensor<16x7x14x14xf32> broadcast_dimensions = []

  %scaled = stablehlo.multiply %biased, %multiplier_broadcast : tensor<16x7x14x14xf32>

  // First global average pooling over dims 2 and 3 (height and width), keepdim=True
  // Reduce mean = sum / (height*width)
