  %divisor0 = stablehlo.constant 196.0 : f32
  %divisor_broadcast0 = stablehlo.broadcast_in_dim %divisor0 : tensor<f32> to tensor<16x7x1x1xf32> broadcast_dimensions = []

  %mean0 = stablehlo.divide %sum0, %divisor_broadcast0 : tensor<16x7x1x1xf32>

