      stablehlo.return %c : tensor<f32>
  } dimensions = [2, 3] : tensor<16x7x1x1xf32> -> tensor<16x7x1x1xf32>

  // Divide by 1*1=1 (no change)
  %divisor1 = stablehlo.constant 1.0 : f32
  %divisor_broadcast1 = stablehlo.broadcast_in_dim %divisor1 : tensor<f32> to tensor<16x7x1x1xf32> broadcast_dimensions = []

  %mean1 = stablehlo.divide %sum1, %divisor_broadcast1 : tensor<16x7x1x1xf32>

  func.return %mean1 : tensor<16x7x1x1xf32>
