  // dimension_numbers: input [b, i, h, w], kernel [i, o, kh, kw], output [b, o, h, w]
  // feature_group_count = 1
  // padding = 0
  // window_strides = 1
  // lhs_dilation = stride = 1
  // rhs_dilation = 1
  %result = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
